window.TREE={"subject":"Area I · Financial Reporting","key":"far_area1_financial_reporting","brand":"Terra Prep","area":"I","law_asof":"2026-09-29","parts":[{"no":1,"name":"Area I · Financial Reporting","chs":["1-01","1-02","1-03","1-04","1-05","1-06"],"color":"--fam-geo"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"For-Profit General-Purpose Financial Reporting","grp":"A","nodes":[1]},{"key":"1-02","part":1,"no":2,"name":"Not-for-Profit Entities","grp":"B","nodes":[2]},{"key":"1-03","part":1,"no":3,"name":"State and Local Governments","grp":"C","nodes":[3]},{"key":"1-04","part":1,"no":4,"name":"Public Company Reporting Topics","grp":"D","nodes":[4]},{"key":"1-05","part":1,"no":5,"name":"Special Purpose Frameworks","grp":"E","nodes":[5]},{"key":"1-06","part":1,"no":6,"name":"Financial Ratios and Performance Analysis","grp":"F","nodes":[6]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"For-Profit General-Purpose Financial Reporting","name":"For-Profit General-Purpose Financial Reporting","vol":46,"q":46,"cs":0,"law":0,"grp":"A"},{"no":2,"part":1,"ch":2,"title":"Not-for-Profit Entities","name":"Not-for-Profit Entities","vol":20,"q":20,"cs":0,"law":0,"grp":"B"},{"no":3,"part":1,"ch":3,"title":"State and Local Governments","name":"State and Local Governments","vol":30,"q":30,"cs":0,"law":0,"grp":"C"},{"no":4,"part":1,"ch":4,"title":"Public Company Reporting Topics","name":"Public Company Reporting Topics","vol":24,"q":24,"cs":0,"law":0,"grp":"D"},{"no":5,"part":1,"ch":5,"title":"Special Purpose Frameworks","name":"Special Purpose Frameworks","vol":12,"q":12,"cs":0,"law":0,"grp":"E"},{"no":6,"part":1,"ch":6,"title":"Financial Ratios and Performance Analysis","name":"Financial Ratios and Performance Analysis","vol":18,"q":18,"cs":0,"law":0,"grp":"F"}],"stat":{"parts":1,"chs":6,"nodes":6,"q":150}};
window.QBANK={"1":[{"i":"FAR-I-A-0001","t":"Northgate Foods is training new accounting staff on the conceptual framework for financial reporting. Which of the following is a fundamental qualitative characteristic of useful financial information?","mc":{"s":"Northgate Foods is training new accounting staff on the conceptual framework for financial reporting. Which of the following is a fundamental qualitative characteristic of useful financial information?","d":"","o":["Comparability","Verifiability","Timeliness","Faithful representation"],"a":4,"cite":"SFAC 8","rat":"The two fundamental qualitative characteristics are relevance and faithful representation.","ex":["Comparability is an enhancing characteristic. It improves usefulness only after the fundamental characteristics are met.","Verifiability is an enhancing characteristic, not a fundamental one.","Timeliness is an enhancing characteristic; it does not by itself make information useful.","The two fundamental qualitative characteristics are relevance and faithful representation."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Fundamental qualitative characteristics are relevance and faithful representation; comparability, verifiability, timeliness and understandability only enhance them.","from":"2026-01-01"}},{"i":"FAR-I-A-0002","t":"The owner of Ridgeline Bakery, Inc. paid a personal family vacation from the company checking account and recorded it as office expense. Which basic accounting assumption does this treatment violate?","mc":{"s":"The owner of Ridgeline Bakery, Inc. paid a personal family vacation from the company checking account and recorded it as office expense. Which basic accounting assumption does this treatment violate?","d":"","o":["Going concern assumption","Periodicity assumption","Monetary unit assumption","Economic entity assumption"],"a":4,"cite":"SFAC 8","rat":"The business must be accounted for separately from its owner's personal affairs, so personal spending is not a company expense.","ex":["Going concern concerns whether the entity will continue operating; it says nothing about separating owner and business.","Periodicity divides the entity's life into reporting periods; the vacation cost does not misstate a period boundary.","The monetary unit assumption is that transactions are measured in a stable currency, which is not at issue here.","The business must be accounted for separately from its owner's personal affairs, so personal spending is not a company expense."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"The economic entity assumption keeps an entity's transactions separate from those of its owners and other entities.","from":"2026-01-01"}},{"i":"FAR-I-A-0003","t":"Cedar Point Manufacturing sold a parcel of land that it had held for future use, for $40,000 more than its carrying amount. Which characterization is most consistent with the conceptual framework?","mc":{"s":"Cedar Point Manufacturing sold a parcel of land that it had held for future use, for $40,000 more than its carrying amount. Which characterization is most consistent with the conceptual framework?","d":"","o":["Revenue, because the sale increased net assets during the period","Other comprehensive income, because the sale was not part of operations","A reduction of expense, because the proceeds exceeded the carrying amount","A gain, because it results from a peripheral or incidental transaction"],"a":4,"cite":"SFAC 6","rat":"Increases in net assets from peripheral or incidental transactions are gains; they are reported in net income here because the land is not available-for-sale debt.","ex":["Revenue arises from an entity's ongoing major or central operations. Selling idle land is incidental, so the increase is a gain.","OCI is limited to items the standards specifically direct to OCI. A realized gain on land is recognized in net income.","The excess of proceeds over carrying amount is not a recovery of a prior cost; it is a separate gain.","Increases in net assets from peripheral or incidental transactions are gains; they are reported in net income here because the land is not available-for-sale debt."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Gains are increases in net assets from peripheral or incidental transactions; revenues come from ongoing major or central operations.","from":"2026-01-01"}},{"i":"FAR-I-A-0004","t":"Glenrock Technologies, a public company, will issue its financial statements for the year ended December 31, 2026 on March 10, 2027. Management is evaluating whether conditions raise substantial doubt about the entity's ability to continue as a going concern. Through what date must management's evaluation look forward?","mc":{"s":"Glenrock Technologies, a public company, will issue its financial statements for the year ended December 31, 2026 on March 10, 2027. Management is evaluating whether conditions raise substantial doubt about the entity's ability to continue as a going concern. Through what date must management's evaluation look forward?","d":"","o":["December 31, 2027","December 31, 2028","March 10, 2027","March 10, 2028"],"a":4,"cite":"ASC 205","rat":"The evaluation covers one year after the date the financial statements are issued (or available to be issued).","ex":["One year after the balance sheet date is the old auditor-style horizon. The horizon runs from the issuance date, not the balance sheet date.","This is one year after the end of the next fiscal year, which extends the horizon beyond the required period.","This is the issuance date itself. The evaluation looks forward one year from that date.","The evaluation covers one year after the date the financial statements are issued (or available to be issued)."],"wt":["trap","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Management evaluates going concern for one year after the date the financial statements are issued or available to be issued.","from":"2026-01-01"}},{"i":"FAR-I-A-0005","t":"At December 31, 2026, Bayfront Marine had recurring operating losses and a $2.4 million loan maturing in June 2027 that it cannot repay from existing resources. Management's only plan is to sell a vessel to a buyer not yet identified, and the plan is not probable of being effectively implemented. Which disclosure is required in the notes?","mc":{"s":"At December 31, 2026, Bayfront Marine had recurring operating losses and a $2.4 million loan maturing in June 2027 that it cannot repay from existing resources. Management's only plan is to sell a vessel to a buyer not yet identified, and the plan is not probable of being effectively implemented. Which disclosure is required in the notes?","d":"","o":["The principal conditions and management's plans only, because the words 'substantial doubt' are reserved for the auditor's report","The principal conditions and a statement that management's plans have alleviated the substantial doubt about continuing as a going concern","No note disclosure, because a going concern assessment is required only in the auditor's report and management letter","The principal conditions, management's evaluation and plans, and a statement that substantial doubt exists about the ability to continue as a going concern"],"a":4,"cite":"ASC 205","rat":"When plans do not alleviate the doubt, the notes must state that substantial doubt exists in addition to describing conditions, evaluation and plans.","ex":["Management's own disclosure must include the substantial doubt statement. The auditor's report is a separate communication.","Plans alleviate doubt only when it is probable they will be effectively implemented and will mitigate the conditions. Neither is true here.","GAAP requires management to evaluate and disclose; the disclosure is not left to the auditor.","When plans do not alleviate the doubt, the notes must state that substantial doubt exists in addition to describing conditions, evaluation and plans."],"wt":["concept","trap","concept",""],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"If plans do not alleviate substantial doubt, disclose the conditions, evaluation, plans and an explicit substantial-doubt statement.","from":"2026-01-01"}},{"i":"FAR-I-A-0006","t":"Riverbend Co. will issue its December 31, 2026 financial statements on March 5, 2027. Its liabilities at year-end include accounts payable of $250,000, accrued wages of $40,000, current maturities of long-term debt of $100,000, and dividends payable of $30,000. It also has a $600,000 note payable due February 15, 2027. On January 20, 2027, Riverbend issued $700,000 of five-year bonds and used the proceeds to repay the note when due. What amount should Riverbend report as total current liabilities at December 31, 2026?","mc":{"s":"Riverbend Co. will issue its December 31, 2026 financial statements on March 5, 2027. Its liabilities at year-end include accounts payable of $250,000, accrued wages of $40,000, current maturities of long-term debt of $100,000, and dividends payable of $30,000. It also has a $600,000 note payable due February 15, 2027. On January 20, 2027, Riverbend issued $700,000 of five-year bonds and used the proceeds to repay the note when due. What amount should Riverbend report as total current liabilities at December 31, 2026?","d":"","o":["$320,000","$390,000","$420,000","$1,020,000"],"a":3,"cite":"ASC 470","rat":"The note is excluded because long-term financing was completed before the statements were issued: $250,000 + $40,000 + $100,000 + $30,000 = $420,000.","ex":["Omits the $100,000 current maturities of long-term debt, which are due within the next year and remain current.","Omits the $30,000 dividends payable. Declared dividends are a current liability.","The note is excluded because long-term financing was completed before the statements were issued: $250,000 + $40,000 + $100,000 + $30,000 = $420,000.","Includes the $600,000 note. A short-term obligation refinanced on a long-term basis before issuance of the statements is classified as noncurrent."],"wt":["concept","concept","","trap"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A short-term obligation is noncurrent if, before the statements are issued, it is refinanced by issuing long-term debt or equity.","from":"2026-01-01","calc":1,"steps":["Current items: AP 250000 + wages 40000 + current maturities 100000 + dividends 30000 = 420000","Note refinanced with bonds issued Jan 20, 2027 (before Mar 5, 2027 issuance): noncurrent, excluded"]}},{"i":"FAR-I-A-0007","t":"Harlow Corp. had these balances at December 31, 2026: cash $80,000; cash restricted for a plant expansion to be built in 2028, $50,000; accounts receivable $210,000 with an allowance for credit losses of $10,000; inventory $150,000; prepaid insurance $45,000 covering the next 18 months, of which $30,000 will be used up within 12 months of the balance sheet date and $15,000 after that; trading securities $40,000; and an equity-method investment in an affiliate, $90,000. What amount should Harlow report as total current assets?","mc":{"s":"Harlow Corp. had these balances at December 31, 2026: cash $80,000; cash restricted for a plant expansion to be built in 2028, $50,000; accounts receivable $210,000 with an allowance for credit losses of $10,000; inventory $150,000; prepaid insurance $45,000 covering the next 18 months, of which $30,000 will be used up within 12 months of the balance sheet date and $15,000 after that; trading securities $40,000; and an equity-method investment in an affiliate, $90,000. What amount should Harlow report as total current assets?","d":"","o":["$500,000","$515,000","$550,000","$590,000"],"a":1,"cite":"ASC 210","rat":"$80,000 + net receivables $200,000 + inventory $150,000 + prepaid insurance for 12 of 18 months $30,000 + trading securities $40,000 = $500,000.","ex":["$80,000 + net receivables $200,000 + inventory $150,000 + prepaid insurance for 12 of 18 months $30,000 + trading securities $40,000 = $500,000.","Treats the whole $45,000 of prepaid insurance as current. Only the portion expiring within the next 12 months is current.","Includes the $50,000 of restricted cash. Cash restricted for a noncurrent purpose is a noncurrent asset.","Includes the $90,000 equity-method investment. It is a long-term investment, not a current asset."],"wt":["","calc","concept","concept"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Current assets are those expected to be realized or used within one year or the operating cycle; restricted cash for long-term uses is not current.","from":"2026-01-01","calc":1,"steps":["Prepaid current portion 45,000 x 12/18 = 30000","80000 + 200000 + 150000 + 30000 + 40000 = 500000"]}},{"i":"FAR-I-A-0008","t":"On July 1, 2026, Sable Analytics received $1,200,000 for a 24-month software subscription that began that day. Revenue is recognized evenly over the term. What amount should Sable report as a noncurrent contract liability (deferred revenue) at December 31, 2026?","mc":{"s":"On July 1, 2026, Sable Analytics received $1,200,000 for a 24-month software subscription that began that day. Revenue is recognized evenly over the term. What amount should Sable report as a noncurrent contract liability (deferred revenue) at December 31, 2026?","d":"","o":["$300,000","$600,000","$900,000","$1,200,000"],"a":1,"cite":"ASC 210","rat":"Six months (through Dec 31, 2026) is recognized; 18 months remain.","ex":["Six months (through Dec 31, 2026) is recognized; 18 months remain. The next 12 months ($600,000) are current, so $300,000 is noncurrent.","This is the current portion for the next 12 months, not the noncurrent portion.","This is the entire remaining contract liability (18 of 24 months). Part of it is current.","This is the full amount received, ignoring the six months already earned."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Split a contract liability into the portion recognized within 12 months (current) and the remainder (noncurrent).","from":"2026-01-01","calc":1,"steps":["Monthly revenue 1,200,000/24 = 50,000","Earned through Dec 31, 2026: 6 x 50,000 = 300,000; remaining 900,000","Next 12 months 600,000 current; remaining 300,000 noncurrent"]}},{"i":"FAR-I-A-0009","t":"Marlow Inc. operates in a single tax jurisdiction. At December 31, 2026 it has deferred tax assets of $40,000 (from an accrued warranty liability, a current-type item) and deferred tax liabilities of $100,000 (from accelerated depreciation). How should Marlow present these amounts on its classified balance sheet?","mc":{"s":"Marlow Inc. operates in a single tax jurisdiction. At December 31, 2026 it has deferred tax assets of $40,000 (from an accrued warranty liability, a current-type item) and deferred tax liabilities of $100,000 (from accelerated depreciation). How should Marlow present these amounts on its classified balance sheet?","d":"","o":["A current deferred tax asset of $40,000 and a noncurrent deferred tax liability of $100,000","A current deferred tax liability of $60,000","A noncurrent deferred tax asset of $40,000 and a noncurrent deferred tax liability of $100,000, shown separately","A single noncurrent deferred tax liability of $60,000"],"a":4,"cite":"ASC 740","rat":"Deferred tax assets and liabilities of the same jurisdiction are netted and classified as noncurrent.","ex":["Classification by the related asset or liability was eliminated. All deferred taxes are noncurrent and same-jurisdiction amounts are netted.","The net amount is a noncurrent liability; no deferred tax amount is classified as current.","They are noncurrent, but same-jurisdiction assets and liabilities must be offset and shown as one net amount.","Deferred tax assets and liabilities of the same jurisdiction are netted and classified as noncurrent."],"wt":["concept","concept","trap",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"All deferred tax balances are noncurrent, and those of the same tax-paying component and jurisdiction are netted.","from":"2026-01-01"}},{"i":"FAR-I-A-0010","t":"At December 31, 2026, Larkin Corp. had a checking account with a balance of $85,000 at First Bank and an overdraft of $20,000 in a separate account at Second Bank. Larkin has no right of offset between the two banks. What amount should Larkin report as cash in current assets?","mc":{"s":"At December 31, 2026, Larkin Corp. had a checking account with a balance of $85,000 at First Bank and an overdraft of $20,000 in a separate account at Second Bank. Larkin has no right of offset between the two banks. What amount should Larkin report as cash in current assets?","d":"","o":["$20,000","$65,000","$85,000","$105,000"],"a":3,"cite":"ASC 210","rat":"The $20,000 overdraft is reported as a current liability because it is at a different bank, so cash stays $85,000.","ex":["Reports only the overdraft amount, which is a liability rather than cash.","Nets the overdraft against the positive balance. Offsetting is allowed only for accounts at the same bank with a right of offset.","The $20,000 overdraft is reported as a current liability because it is at a different bank, so cash stays $85,000.","Adds the overdraft to cash. An overdraft never increases the cash asset."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Overdrafts are reported as liabilities and offset against positive balances only for accounts at the same bank with a right of offset.","from":"2026-01-01","calc":1,"steps":["Cash = 85000; overdraft 20000 reported separately as a current liability"]}},{"i":"FAR-I-A-0011","t":"Which of the following must be included in a company's summary of significant accounting policies?","mc":{"s":"Which of the following must be included in a company's summary of significant accounting policies?","d":"","o":["The balance of each customer account included in accounts receivable, broken out by customer","The dates and amounts of every journal entry that adjusted the trial balance at year-end","A forecast of next year's revenue and net income prepared by management","The cost-flow assumption used to value inventory, when more than one acceptable method exists"],"a":4,"cite":"ASC 235","rat":"Policies that management selected from acceptable alternatives (for example, inventory methods) must be disclosed.","ex":["Account-level detail is not a policy disclosure; policies describe the methods used, not individual balances.","Journal entries are internal records, not policy disclosures.","Forecasts are not part of the basic financial statements or the policy note.","Policies that management selected from acceptable alternatives (for example, inventory methods) must be disclosed."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Disclose accounting policies that management selected from acceptable alternatives, including industry-specific and unusual applications.","from":"2026-01-01"}},{"i":"FAR-I-A-0012","t":"At December 31, 2026, Quarry Hill Co. violated a covenant on its $3 million term loan due in 2031, making the loan callable by the lender. Before issuing its statements on March 1, 2027, Quarry Hill obtained a written waiver from the lender covering the violation and waiving the lender's right to demand repayment for 15 months from December 31, 2026. How should the loan be classified at December 31, 2026?","mc":{"s":"At December 31, 2026, Quarry Hill Co. violated a covenant on its $3 million term loan due in 2031, making the loan callable by the lender. Before issuing its statements on March 1, 2027, Quarry Hill obtained a written waiver from the lender covering the violation and waiving the lender's right to demand repayment for 15 months from December 31, 2026. How should the loan be classified at December 31, 2026?","d":"","o":["Current, because the covenant was violated at the balance sheet date and the loan was therefore callable then","Current, because the waiver period ends only 3 months after the next fiscal year begins","Noncurrent, but only if the violation is also cured by the end of the year following the balance sheet date","Noncurrent, because the lender waived the right to demand repayment for more than one year from the balance sheet date"],"a":4,"cite":"ASC 470","rat":"A callable obligation is noncurrent only if the creditor has waived or lost the right to demand repayment for more than one year from the balance sheet date.","ex":["The waiver obtained before issuance, covering more than one year, removes the current classification.","A waiver longer than one year from the balance sheet date is sufficient; its end date within the next year is irrelevant.","A waiver for more than one year is sufficient on its own; cure is an alternative route, not an additional requirement.","A callable obligation is noncurrent only if the creditor has waived or lost the right to demand repayment for more than one year from the balance sheet date."],"wt":["trap","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A covenant-violating loan stays noncurrent only if the lender waives its right to call it for over one year from the balance sheet date.","from":"2026-01-01"}},{"i":"FAR-I-A-0013","t":"Fenwick Corp.'s board voted in December 2026 to buy a new machine in March 2027 for $500,000 on credit. No purchase order has been signed and no goods were received. Under the conceptual framework, how should Fenwick treat the plan at December 31, 2026?","mc":{"s":"Fenwick Corp.'s board voted in December 2026 to buy a new machine in March 2027 for $500,000 on credit. No purchase order has been signed and no goods were received. Under the conceptual framework, how should Fenwick treat the plan at December 31, 2026?","d":"","o":["Recognize a liability of $500,000, because the board's vote is a probable future sacrifice of economic benefits","Recognize an asset of $500,000, because the board has committed the entity to control the machine's benefits","Recognize an appropriation of retained earnings of $500,000, because the board has designated resources for it","Do not recognize a liability, because no past transaction or event has created a present obligation to transfer assets"],"a":4,"cite":"SFAC 6","rat":"A liability requires a present obligation arising from past transactions or events; a planned future purchase is not one.","ex":["A probable future sacrifice is only one part of the definition; the obligation must also be present and arise from a past event.","No asset exists until the entity obtains control of the machine's future benefits through a past transaction.","Board designations do not create a liability or a reduction of equity in the financial statements.","A liability requires a present obligation arising from past transactions or events; a planned future purchase is not one."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"A liability is a present obligation to transfer assets, arising from past transactions or events; management intentions alone do not create one.","from":"2026-01-01"}},{"i":"FAR-I-A-0014","t":"For 2026, Tamarack Products reported: gross sales $900,000; sales returns $30,000; sales discounts $20,000; cost of goods sold $510,000; selling and administrative expenses $140,000; interest expense $25,000; interest income $5,000; loss on sale of equipment $12,000; and a $18,000 gain from an insurance recovery after a hurricane, an event that was unusual and infrequent. Tamarack also had a $35,000 loss, net of tax, from a discontinued component. What amount should Tamarack report as income from continuing operations before income taxes?","mc":{"s":"For 2026, Tamarack Products reported: gross sales $900,000; sales returns $30,000; sales discounts $20,000; cost of goods sold $510,000; selling and administrative expenses $140,000; interest expense $25,000; interest income $5,000; loss on sale of equipment $12,000; and a $18,000 gain from an insurance recovery after a hurricane, an event that was unusual and infrequent. Tamarack also had a $35,000 loss, net of tax, from a discontinued component. What amount should Tamarack report as income from continuing operations before income taxes?","d":"","o":["$151,000","$168,000","$186,000","$221,000"],"a":3,"cite":"ASC 225; ASC 205","rat":"Net sales $850,000 less cost of goods sold, expenses, interest and the equipment loss, plus interest income and the unusual gain, gives $186,000.","ex":["Deducts the $35,000 discontinued-operations loss. That loss is presented separately after continuing operations, net of tax.","Excludes the $18,000 hurricane gain as if it were an extraordinary item. Extraordinary-item presentation was eliminated; unusual or infrequent items stay in continuing operations.","Net sales $850,000 less cost of goods sold, expenses, interest and the equipment loss, plus interest income and the unusual gain, gives $186,000.","Adds the $35,000 discontinued-operations loss. It is presented separately, and it is a loss, not an addition."],"wt":["concept","concept","","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Unusual or infrequent items remain in income from continuing operations; discontinued operations are shown separately below, net of tax.","from":"2026-01-01","calc":1,"steps":["Net sales 900000-30000-20000 = 850000","Less COGS 510000 and S&A 140000: 200000","Less interest expense 25000, plus interest income 5000, less equipment loss 12000, plus hurricane gain 18000: 186000"]}},{"i":"FAR-I-A-0015","t":"In 2026, the board of Fairbank Industries committed to sell its wholesale division, a strategic shift that qualifies for discontinued operations reporting. Through the disposal date the division earned pretax income of $180,000, and the disposal produced a pretax loss of $60,000. Fairbank's income tax rate is 30%. What amount should be reported in the income statement as income from discontinued operations, net of tax?","mc":{"s":"In 2026, the board of Fairbank Industries committed to sell its wholesale division, a strategic shift that qualifies for discontinued operations reporting. Through the disposal date the division earned pretax income of $180,000, and the disposal produced a pretax loss of $60,000. Fairbank's income tax rate is 30%. What amount should be reported in the income statement as income from discontinued operations, net of tax?","d":"","o":["$84,000","$120,000","$126,000","$168,000"],"a":1,"cite":"ASC 205","rat":"Operating income $180,000 less the disposal loss $60,000 is $120,000 pretax; after 30% tax it is $84,000.","ex":["Operating income $180,000 less the disposal loss $60,000 is $120,000 pretax; after 30% tax it is $84,000.","Reports the combined result before tax ($120,000). Discontinued operations are presented net of tax.","Includes only the operating income after tax ($126,000) and omits the loss on disposal, which is part of discontinued operations.","Adds the disposal loss to operating income. A loss reduces the result."],"wt":["","concept","concept","calc"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Report the disposal component's operating results and disposal gain or loss together, net of tax, below continuing operations.","from":"2026-01-01","calc":1,"steps":["Pretax result 180000 - 60000 = 120000","After tax 120000 x (1 - 0.30) = 84000"]}},{"i":"FAR-I-A-0016","t":"During 2026, four companies disposed of businesses. Which disposal most clearly qualifies for presentation as a discontinued operation?","mc":{"s":"During 2026, four companies disposed of businesses. Which disposal most clearly qualifies for presentation as a discontinued operation?","d":"","o":["Quill Retail closed one of its 240 stores, which generated less than 1% of revenue and profit, because the lease expired","Dunmore Foods sold one production line at its main plant and replaced it with a newer line producing the same products","Ashby Co. sold its headquarters building and moved into leased space, continuing all of its lines of business unchanged","Ellery Corp. sold its entire European division, which produced 35% of consolidated revenue, ending its strategy of operating outside North America"],"a":4,"cite":"ASC 205","rat":"The disposal of a component that represents a strategic shift with a major effect on operations and results qualifies.","ex":["A single small store is not a strategic shift and has no major effect on results.","Replacing equipment within the same business is not a strategic shift or disposal of a component.","Selling an asset while continuing the business does not dispose of a component.","The disposal of a component that represents a strategic shift with a major effect on operations and results qualifies."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A discontinued operation is a component disposal that represents a strategic shift with a major effect on the entity's operations and financial results.","from":"2026-01-01"}},{"i":"FAR-I-A-0017","t":"At December 31, 2026, Westmere Co. classified a disposal group as held for sale. Its carrying amount was $900,000, its fair value was $780,000, and estimated costs to sell were $40,000. What loss should Westmere recognize at December 31, 2026?","mc":{"s":"At December 31, 2026, Westmere Co. classified a disposal group as held for sale. Its carrying amount was $900,000, its fair value was $780,000, and estimated costs to sell were $40,000. What loss should Westmere recognize at December 31, 2026?","d":"","o":["$40,000","$80,000","$120,000","$160,000"],"a":4,"cite":"ASC 360","rat":"Held-for-sale assets are measured at the lower of carrying amount or fair value less costs to sell: $900,000 - ($780,000 - $40,000) = $160,000.","ex":["Recognizes only the $40,000 of selling costs and ignores the decline from carrying amount to fair value.","Adds the costs to sell to fair value instead of subtracting them.","Uses fair value alone ($120,000); costs to sell must also be deducted.","Held-for-sale assets are measured at the lower of carrying amount or fair value less costs to sell: $900,000 - ($780,000 - $40,000) = $160,000."],"wt":["calc","calc","calc",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Held-for-sale assets are measured at the lower of carrying amount or fair value less costs to sell; write-downs are losses.","from":"2026-01-01","calc":1,"steps":["Fair value less costs to sell 780000 - 40000 = 740000","Loss 900000 - 740000 = 160000"]}},{"i":"FAR-I-A-0018","t":"Coldwater Shipping is located in a region with no history of tornadoes. In 2026 a tornado destroyed a warehouse, causing an uninsured pretax loss of $2 million; neither the event nor its type is expected to recur. How should Coldwater present the loss?","mc":{"s":"Coldwater Shipping is located in a region with no history of tornadoes. In 2026 a tornado destroyed a warehouse, causing an uninsured pretax loss of $2 million; neither the event nor its type is expected to recur. How should Coldwater present the loss?","d":"","o":["As a separate component of income from continuing operations, before income taxes, or in the notes","As an extraordinary item, net of tax, below income from continuing operations","As a loss from discontinued operations, net of tax, because it will not recur","As a direct charge to retained earnings, because it is outside the normal operations of the entity"],"a":1,"cite":"ASC 225","rat":"Items that are unusual or infrequent are reported within income from continuing operations and separately identified.","ex":["Items that are unusual or infrequent are reported within income from continuing operations and separately identified.","The extraordinary item category was eliminated by ASU 2015-01. Such items stay in continuing operations.","Discontinued operations relate to the disposal of a component, not to an isolated casualty loss.","Losses flow through net income; direct charges to retained earnings apply only to specific items like error corrections."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Unusual or infrequent items are presented as a separate component of income from continuing operations, not as extraordinary items.","from":"2026-01-01"}},{"i":"FAR-I-A-0019","t":"Halston Co. reported net income of $500,000 for 2026. Other items: unrealized holding gains on available-for-sale debt securities, net of tax, $30,000; a foreign currency translation loss, net of tax, $20,000; a net actuarial loss on its defined benefit pension plan, net of tax, $15,000; and a $25,000 unrealized gain on equity securities carried at fair value through net income, which is already included in net income. What is Halston's total comprehensive income for 2026?","mc":{"s":"Halston Co. reported net income of $500,000 for 2026. Other items: unrealized holding gains on available-for-sale debt securities, net of tax, $30,000; a foreign currency translation loss, net of tax, $20,000; a net actuarial loss on its defined benefit pension plan, net of tax, $15,000; and a $25,000 unrealized gain on equity securities carried at fair value through net income, which is already included in net income. What is Halston's total comprehensive income for 2026?","d":"","o":["$495,000","$510,000","$520,000","$535,000"],"a":1,"cite":"ASC 220","rat":"Net income $500,000 + $30,000 - $20,000 - $15,000 of other comprehensive income = $495,000.","ex":["Net income $500,000 + $30,000 - $20,000 - $15,000 of other comprehensive income = $495,000.","Omits the $15,000 pension loss, which is an item of other comprehensive income.","Adds the $25,000 equity-securities gain again; it is already in net income.","Adds the translation loss instead of subtracting it."],"wt":["","calc","trap","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Comprehensive income equals net income plus other comprehensive income items such as AFS gains, translation adjustments and pension gains or losses.","from":"2026-01-01","calc":1,"steps":["OCI = 30000 - 20000 - 15000 = -5000","Comprehensive income = 500000 + -5000 = 495000"]}},{"i":"FAR-I-A-0020","t":"Halden Inc. owns available-for-sale debt securities that cost $100,000. At December 31, 2025 their fair value was $125,000, and accumulated other comprehensive income included a $25,000 unrealized gain. In 2026 Halden sold the securities for $140,000. Ignoring income taxes, what amount is reclassified out of accumulated other comprehensive income into net income in 2026?","mc":{"s":"Halden Inc. owns available-for-sale debt securities that cost $100,000. At December 31, 2025 their fair value was $125,000, and accumulated other comprehensive income included a $25,000 unrealized gain. In 2026 Halden sold the securities for $140,000. Ignoring income taxes, what amount is reclassified out of accumulated other comprehensive income into net income in 2026?","d":"","o":["$15,000","$25,000","$40,000","$65,000"],"a":3,"cite":"ASC 220; ASC 320","rat":"The whole accumulated gain ($140,000 - $100,000 = $40,000) becomes realized and is reclassified; net income reports the $40,000 gain.","ex":["Uses only the gain arising in 2026 ($15,000); the earlier $25,000 sits in AOCI and must also be reclassified.","Uses only the beginning AOCI balance ($25,000). The $15,000 gain arising in 2026 (fair value $125,000 to $140,000) first flows through OCI, so the whole $40,000 is in AOCI just before the sale and is reclassified.","The whole accumulated gain ($140,000 - $100,000 = $40,000) becomes realized and is reclassified; net income reports the $40,000 gain.","Adds the beginning AOCI balance to the total realized gain, double counting the $25,000."],"wt":["concept","concept","","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"When available-for-sale securities are sold, the cumulative unrealized gain or loss in AOCI is reclassified to net income.","from":"2026-01-01","calc":1,"steps":["Realized gain 140000 - 100000 = 40000","OCI for 2026 = unrealized gain 15000 - reclassification 40000 = -25000; AOCI ends at 0"]}},{"i":"FAR-I-A-0021","t":"Brightwater Corp., a business entity, has items of other comprehensive income in 2026. Which presentation is permitted?","mc":{"s":"Brightwater Corp., a business entity, has items of other comprehensive income in 2026. Which presentation is permitted?","d":"","o":["A single continuous statement of comprehensive income, or two separate consecutive statements, the income statement followed by a statement of other comprehensive income","Other comprehensive income shown only as part of the statement of changes in stockholders' equity, with no separate performance statement","Other comprehensive income disclosed only in the notes to the financial statements, with totals shown on the balance sheet","Two separate statements presented in different sections of the annual report, with the OCI statement appearing before the income statement"],"a":1,"cite":"ASC 220","rat":"Both the one-statement and two-statement approaches are allowed, and the two statements must be presented consecutively.","ex":["Both the one-statement and two-statement approaches are allowed, and the two statements must be presented consecutively.","This option was eliminated; OCI must be shown in a performance statement, not solely in the equity statement.","Disclosure in the notes alone does not meet the requirement to present OCI in a statement.","Two-statement presentation requires the OCI statement to follow the income statement immediately."],"wt":["","concept","concept","trap"],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"OCI is presented in one continuous statement or in two consecutive statements; the equity statement alone is not allowed.","from":"2026-01-01"}},{"i":"FAR-I-A-0022","t":"Pinecrest Supply reported net sales of $1,250,000 for 2026. Beginning inventory was $180,000, purchases were $900,000, purchase returns were $40,000, freight-in was $30,000, and ending inventory was $220,000. What is Pinecrest's gross profit?","mc":{"s":"Pinecrest Supply reported net sales of $1,250,000 for 2026. Beginning inventory was $180,000, purchases were $900,000, purchase returns were $40,000, freight-in was $30,000, and ending inventory was $220,000. What is Pinecrest's gross profit?","d":"","o":["$320,000","$360,000","$400,000","$430,000"],"a":3,"cite":"ASC 330","rat":"Cost of goods sold = $180,000 + $900,000 - $40,000 + $30,000 - $220,000 = $850,000; gross profit = $1,250,000 - $850,000 = $400,000.","ex":["Adds purchase returns instead of subtracting them, overstating cost of goods sold.","Ignores the purchase returns, overstating cost of goods sold and understating gross profit.","Cost of goods sold = $180,000 + $900,000 - $40,000 + $30,000 - $220,000 = $850,000; gross profit = $1,250,000 - $850,000 = $400,000.","Omits freight-in, which is part of inventory cost, understating cost of goods sold."],"wt":["calc","calc","","calc"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Cost of goods sold = beginning inventory + net purchases + freight-in - ending inventory; gross profit is net sales minus that amount.","from":"2026-01-01","calc":1,"steps":["Cost of goods available = 180000+900000-40000+30000 = 1070000","COGS = 1070000 - 220000 = 850000","Gross profit = 1250000 - 850000 = 400000"]}},{"i":"FAR-I-A-0023","t":"Ashford Corp.'s retained earnings were $640,000 on January 1, 2026. During 2026 it earned net income of $210,000, declared cash dividends of $80,000, and declared and distributed a 5% common stock dividend of 10,000 shares (par value $10,000; fair value $50,000 at declaration). What is retained earnings at December 31, 2026?","mc":{"s":"Ashford Corp.'s retained earnings were $640,000 on January 1, 2026. During 2026 it earned net income of $210,000, declared cash dividends of $80,000, and declared and distributed a 5% common stock dividend of 10,000 shares (par value $10,000; fair value $50,000 at declaration). What is retained earnings at December 31, 2026?","d":"","o":["$720,000","$760,000","$770,000","$850,000"],"a":1,"cite":"ASC 505","rat":"A small stock dividend is charged to retained earnings at fair value: $640,000 + $210,000 - $80,000 - $50,000 = $720,000.","ex":["A small stock dividend is charged to retained earnings at fair value: $640,000 + $210,000 - $80,000 - $50,000 = $720,000.","Charges only the par value ($10,000) for the stock dividend. A small stock dividend transfers fair value.","Ignores the stock dividend entirely; it reduces retained earnings even though no assets leave.","Ignores both the cash dividend and the stock dividend."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A small stock dividend (under 20-25%) transfers the shares' fair value from retained earnings to paid-in capital.","from":"2026-01-01","calc":1,"steps":["640000 + 210000 - 80000 - 50000 = 720000"]}},{"i":"FAR-I-A-0024","t":"Total stockholders' equity of Overton Co. was $2,000,000 on January 1, 2026. During 2026 Overton earned net income of $300,000, had other comprehensive loss of $40,000, declared cash dividends of $120,000, issued common stock for $250,000, and purchased treasury stock for $90,000. What is total stockholders' equity on December 31, 2026?","mc":{"s":"Total stockholders' equity of Overton Co. was $2,000,000 on January 1, 2026. During 2026 Overton earned net income of $300,000, had other comprehensive loss of $40,000, declared cash dividends of $120,000, issued common stock for $250,000, and purchased treasury stock for $90,000. What is total stockholders' equity on December 31, 2026?","d":"","o":["$2,300,000","$2,340,000","$2,420,000","$2,480,000"],"a":1,"cite":"ASC 505","rat":"$2,000,000 + $300,000 - $40,000 - $120,000 + $250,000 - $90,000 = $2,300,000.","ex":["$2,000,000 + $300,000 - $40,000 - $120,000 + $250,000 - $90,000 = $2,300,000.","Ignores the $40,000 other comprehensive loss, which reduces accumulated other comprehensive income and total equity.","Does not deduct the $120,000 declared dividends, which reduce retained earnings.","Adds the treasury stock purchase. Treasury stock is a contra-equity account that reduces total equity."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Total equity changes by net income, OCI, dividends, stock issuances and treasury stock transactions.","from":"2026-01-01","calc":1,"steps":["2000000 + 300000 - 40000 - 120000 + 250000 - 90000 = 2300000"]}},{"i":"FAR-I-A-0025","t":"Which of the following items is reported in accumulated other comprehensive income rather than in net income?","mc":{"s":"Which of the following items is reported in accumulated other comprehensive income rather than in net income?","d":"","o":["Unrealized holding gains on equity securities with readily determinable fair values","Unrealized holding gains on debt securities classified as trading","A realized gain on the sale of an unused warehouse building","Unrealized holding gains on available-for-sale debt securities"],"a":4,"cite":"ASC 320; ASC 220","rat":"Unrealized gains and losses on available-for-sale debt securities are reported in other comprehensive income.","ex":["Changes in fair value of equity securities are recognized in net income.","Trading securities' unrealized gains and losses are reported in net income.","Realized gains on the sale of assets are recognized in net income.","Unrealized gains and losses on available-for-sale debt securities are reported in other comprehensive income."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"AOCI holds AFS debt unrealized gains and losses, translation adjustments, pension items and cash flow hedge effects, not equity-security fair value changes.","from":"2026-01-01"}},{"i":"FAR-I-A-0026","t":"Wynn Co.'s accumulated other comprehensive income (credit) was $120,000 on January 1, 2026. During 2026, unrealized gains on available-for-sale debt securities arising in the year were $60,000 pretax, and $25,000 pretax of previously recognized gains was reclassified into net income upon sale. The tax rate is 25%. What is AOCI at December 31, 2026?","mc":{"s":"Wynn Co.'s accumulated other comprehensive income (credit) was $120,000 on January 1, 2026. During 2026, unrealized gains on available-for-sale debt securities arising in the year were $60,000 pretax, and $25,000 pretax of previously recognized gains was reclassified into net income upon sale. The tax rate is 25%. What is AOCI at December 31, 2026?","d":"","o":["$146,250","$155,000","$165,000","$183,750"],"a":1,"cite":"ASC 220","rat":"Net OCI is ($60,000 - $25,000) x (1 - 0.25) = $26,250, so AOCI is $146,250.","ex":["Net OCI is ($60,000 - $25,000) x (1 - 0.25) = $26,250, so AOCI is $146,250.","Uses pretax amounts. OCI items are reported net of tax.","Ignores the reclassification adjustment; the $25,000 realized gain leaves AOCI when it enters net income.","Adds the reclassification instead of subtracting it."],"wt":["","calc","concept","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Reclassification adjustments remove previously accumulated gains from AOCI as they enter net income; OCI is net of tax.","from":"2026-01-01","calc":1,"steps":["Net OCI pretax 60000 - 25000 = 35000","After tax 35000 x 0.75 = 26250.0","AOCI = 120000 + 26250.0 = 146250.0"]}},{"i":"FAR-I-A-0027","t":"For 2026, Kestrel Co. reported net income of $320,000, which included depreciation of $90,000, a loss on the sale of equipment of $15,000, and a gain on the sale of an investment of $20,000. During the year accounts receivable increased $40,000, inventory decreased $25,000, accounts payable increased $30,000, and accrued liabilities decreased $12,000. Using the indirect method, what is net cash provided by operating activities?","mc":{"s":"For 2026, Kestrel Co. reported net income of $320,000, which included depreciation of $90,000, a loss on the sale of equipment of $15,000, and a gain on the sale of an investment of $20,000. During the year accounts receivable increased $40,000, inventory decreased $25,000, accounts payable increased $30,000, and accrued liabilities decreased $12,000. Using the indirect method, what is net cash provided by operating activities?","d":"","o":["$378,000","$408,000","$448,000","$488,000"],"a":2,"cite":"ASC 230","rat":"Net income $320,000 + depreciation $90,000 + loss $15,000 - gain $20,000 - increase in receivables $40,000 + decrease in inventory $25,000 + increase in payables $30,000 - decrease in accruals $12,000 = $408,000.","ex":["Subtracts the $15,000 loss on the equipment sale. A loss is a noncash deduction in net income and must be added back.","Net income $320,000 + depreciation $90,000 + loss $15,000 - gain $20,000 - increase in receivables $40,000 + decrease in inventory $25,000 + increase in payables $30,000 - decrease in accruals $12,000 = $408,000.","Adds the $20,000 gain on the investment sale. A gain is subtracted because the cash proceeds belong to investing activities.","Adds the $40,000 increase in receivables. An increase in receivables means revenue was not collected, so it is subtracted."],"wt":["calc","","calc","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Indirect method: add back noncash expenses and losses, subtract gains, then adjust for changes in operating assets and liabilities.","from":"2026-01-01","calc":1,"steps":["320000 + 90000 + 15000 - 20000 = 405000","Working capital: -40000 + 25000 + 30000 - 12000 = 3000","Total = 408000"]}},{"i":"FAR-I-A-0028","t":"During 2026, Lowell Corp. had credit sales of $1,200,000. Gross accounts receivable were $150,000 at January 1 and $190,000 at December 31, and $10,000 of receivables were written off during the year. What amount of cash was collected from customers?","mc":{"s":"During 2026, Lowell Corp. had credit sales of $1,200,000. Gross accounts receivable were $150,000 at January 1 and $190,000 at December 31, and $10,000 of receivables were written off during the year. What amount of cash was collected from customers?","d":"","o":["$1,150,000","$1,160,000","$1,170,000","$1,240,000"],"a":1,"cite":"ASC 230","rat":"Beginning receivables $150,000 + sales $1,200,000 - write-offs $10,000 - ending receivables $190,000 = $1,150,000.","ex":["Beginning receivables $150,000 + sales $1,200,000 - write-offs $10,000 - ending receivables $190,000 = $1,150,000.","Ignores the $10,000 write-offs, which reduce receivables without any cash being received.","Adds the write-offs back to collections instead of removing them from the receivable roll-forward.","Adds the increase in receivables to sales. An increase means sales exceeded collections."],"wt":["","calc","calc","calc"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Cash collected = beginning receivables + sales - write-offs - ending receivables.","from":"2026-01-01","calc":1,"steps":["150000 + 1200000 - 10000 - 190000 = 1150000"]}},{"i":"FAR-I-A-0029","t":"Cost of goods sold for Dunmore Corp. in 2026 was $800,000. Inventory increased from $120,000 to $150,000, and accounts payable to suppliers decreased from $90,000 to $70,000. What amount of cash was paid to suppliers of inventory?","mc":{"s":"Cost of goods sold for Dunmore Corp. in 2026 was $800,000. Inventory increased from $120,000 to $150,000, and accounts payable to suppliers decreased from $90,000 to $70,000. What amount of cash was paid to suppliers of inventory?","d":"","o":["$790,000","$810,000","$830,000","$850,000"],"a":4,"cite":"ASC 230","rat":"Purchases = $800,000 + $30,000 inventory increase = $830,000; a $20,000 decrease in payables means that much more cash was paid: $850,000.","ex":["Subtracts the inventory increase. An increase in inventory means purchases exceeded cost of goods sold.","Subtracts the decrease in payables. Paying down payables raises cash paid above purchases.","Stops at purchases and ignores the change in accounts payable.","Purchases = $800,000 + $30,000 inventory increase = $830,000; a $20,000 decrease in payables means that much more cash was paid: $850,000."],"wt":["calc","calc","calc",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Purchases = cost of goods sold + change in inventory; cash paid = purchases + decrease (or - increase) in accounts payable.","from":"2026-01-01","calc":1,"steps":["Purchases = 800000 + (150000 - 120000) = 830000","Cash paid = 830000 + (90000 - 70000) = 850000"]}},{"i":"FAR-I-A-0030","t":"Vance Co. reported operating expenses of $300,000 for 2026, which included depreciation of $40,000. Prepaid expenses increased $8,000 and accrued expenses payable decreased $12,000. What amount of cash was paid for operating expenses?","mc":{"s":"Vance Co. reported operating expenses of $300,000 for 2026, which included depreciation of $40,000. Prepaid expenses increased $8,000 and accrued expenses payable decreased $12,000. What amount of cash was paid for operating expenses?","d":"","o":["$240,000","$256,000","$280,000","$320,000"],"a":3,"cite":"ASC 230","rat":"$300,000 - $40,000 depreciation + $8,000 increase in prepaids + $12,000 decrease in accruals = $280,000.","ex":["Subtracts both changes. An increase in prepaids and a decrease in accruals both increase the cash paid.","Gets the prepaid sign right but subtracts the decrease in accrued expenses, which actually increases cash paid.","$300,000 - $40,000 depreciation + $8,000 increase in prepaids + $12,000 decrease in accruals = $280,000.","Fails to remove depreciation, a noncash expense."],"wt":["calc","calc","","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Cash paid for expenses = expense - noncash items + increase in prepaids + decrease in accrued liabilities.","from":"2026-01-01","calc":1,"steps":["300000 - 40000 = 260000","+ 8000 + 12000 = 280000"]}},{"i":"FAR-I-A-0031","t":"Ellison Co. had these 2026 cash flows: proceeds from issuing common stock $300,000; purchase of treasury stock $80,000; cash dividends paid $55,000; interest paid $40,000; proceeds from the sale of equipment $60,000; and repayment of the principal of notes payable $120,000. What is net cash provided by financing activities?","mc":{"s":"Ellison Co. had these 2026 cash flows: proceeds from issuing common stock $300,000; purchase of treasury stock $80,000; cash dividends paid $55,000; interest paid $40,000; proceeds from the sale of equipment $60,000; and repayment of the principal of notes payable $120,000. What is net cash provided by financing activities?","d":"","o":["$5,000","$45,000","$105,000","$165,000"],"a":2,"cite":"ASC 230","rat":"$300,000 - $80,000 - $55,000 - $120,000 = $45,000.","ex":["Deducts the $40,000 interest paid. Interest paid is an operating cash flow.","$300,000 - $80,000 - $55,000 - $120,000 = $45,000. Interest paid is operating and the equipment sale is investing.","Includes the $60,000 equipment sale proceeds, which are an investing inflow.","Omits the $120,000 repayment of note principal, a financing outflow."],"wt":["concept","","concept","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Financing activities include stock issuance and repurchase, dividends paid and debt principal; interest paid is operating.","from":"2026-01-01","calc":1,"steps":["300000 - 80000 - 55000 - 120000 = 45000"]}},{"i":"FAR-I-A-0032","t":"Delmar Corp. retired notes payable with a principal amount of $500,000 before maturity by paying the lender $545,000, which included a $45,000 prepayment penalty. Interest was paid separately. What amount of cash outflow should Delmar report in financing activities for the retirement?","mc":{"s":"Delmar Corp. retired notes payable with a principal amount of $500,000 before maturity by paying the lender $545,000, which included a $45,000 prepayment penalty. Interest was paid separately. What amount of cash outflow should Delmar report in financing activities for the retirement?","d":"","o":["$45,000","$455,000","$500,000","$545,000"],"a":4,"cite":"ASC 230","rat":"Cash paid for debt prepayment or extinguishment costs is a financing outflow, so all $545,000 is financing.","ex":["Reports only the penalty in financing. The principal repayment is also a financing outflow.","Subtracts the penalty from principal, which has no basis in the payment made.","Reports only the principal ($500,000) in financing and treats the $45,000 penalty as operating; prepayment costs are also financing.","Cash paid for debt prepayment or extinguishment costs is a financing outflow, so all $545,000 is financing."],"wt":["concept","calc","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Cash payments for debt prepayment or extinguishment costs, including penalties, are financing outflows.","from":"2026-01-01","calc":1,"steps":["500000 + 45000 = 545000"]}},{"i":"FAR-I-A-0033","t":"Which of the following cash flows is classified as an operating activity in the statement of cash flows?","mc":{"s":"Which of the following cash flows is classified as an operating activity in the statement of cash flows?","d":"","o":["Proceeds from selling a delivery truck used in the business","Payment of cash dividends to common shareholders","Proceeds from issuing bonds payable to investors","Interest received on a note receivable from a customer"],"a":4,"cite":"ASC 230","rat":"Interest received is a cash inflow from returns on loans and is operating.","ex":["Proceeds from selling productive assets are investing inflows.","Dividends paid are a financing outflow.","Proceeds from issuing debt are financing inflows.","Interest received is a cash inflow from returns on loans and is operating."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Operating activities include interest received and paid, dividends received, and cash from goods or services; dividends paid are financing.","from":"2026-01-01"}},{"i":"FAR-I-A-0034","t":"Which transaction must be disclosed as a noncash investing and financing activity?","mc":{"s":"Which transaction must be disclosed as a noncash investing and financing activity?","d":"","o":["Acquisition of land by issuing common stock to the seller","Purchase of equipment for cash paid at delivery","Payment of interest on a note payable at maturity","Sale of equipment for cash at a loss"],"a":1,"cite":"ASC 230","rat":"Investing and financing transactions that do not involve cash are disclosed separately from the statement.","ex":["Investing and financing transactions that do not involve cash are disclosed separately from the statement.","A cash purchase appears in the investing section of the statement, not in the noncash disclosure.","Interest paid is an operating cash flow and is disclosed as supplemental cash paid, not as a noncash transaction.","A cash sale is an investing inflow, and the loss is a noncash adjustment in operating activities."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Investing and financing transactions that affect no cash are disclosed separately, for example acquiring assets by issuing stock or debt.","from":"2026-01-01"}},{"i":"FAR-I-A-0035","t":"Statement of cash flows data for Amity Co. for 2026: cash and cash equivalents were $200,000 at the beginning and $260,000 at the end; restricted cash was $50,000 at the beginning and $80,000 at the end. Net cash provided by operating activities was $300,000 and net cash used in investing activities was $410,000. What was net cash provided by financing activities?","mc":{"s":"Statement of cash flows data for Amity Co. for 2026: cash and cash equivalents were $200,000 at the beginning and $260,000 at the end; restricted cash was $50,000 at the beginning and $80,000 at the end. Net cash provided by operating activities was $300,000 and net cash used in investing activities was $410,000. What was net cash provided by financing activities?","d":"","o":["$140,000","$170,000","$200,000","$250,000"],"a":3,"cite":"ASC 230","rat":"The statement explains the change in cash, equivalents and restricted cash: ($340,000 - $250,000) = $90,000; financing = $90,000 - $300,000 + $410,000 = $200,000.","ex":["Subtracts the increase in restricted cash instead of including it in the change being explained.","Uses only the change in unrestricted cash ($60,000); restricted cash must be included in the total explained.","The statement explains the change in cash, equivalents and restricted cash: ($340,000 - $250,000) = $90,000; financing = $90,000 - $300,000 + $410,000 = $200,000.","Compares ending cash including restricted with beginning cash excluding restricted, leaving the beginning restricted cash out."],"wt":["calc","concept","","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"The statement of cash flows explains the change in total cash, cash equivalents and restricted cash.","from":"2026-01-01","calc":1,"steps":["Ending total 260000+80000 = 340000; beginning total 200000+50000 = 250000; change 90000","Financing = 90000 - 300000 + 410000 = 200000"]}},{"i":"FAR-I-A-0036","t":"Harbor Point Co. prepares its statement of cash flows using the indirect method. Dividends of $90,000 were declared and paid during 2026. There were no disposals of property or equipment, and the entire change in accumulated depreciation is 2026 depreciation expense. What is net cash provided by operating activities for 2026?","mc":{"s":"Harbor Point Co. prepares its statement of cash flows using the indirect method. Dividends of $90,000 were declared and paid during 2026. There were no disposals of property or equipment, and the entire change in accumulated depreciation is 2026 depreciation expense. What is net cash provided by operating activities for 2026?","d":"","o":["$172,000","$192,000","$222,000","$262,000"],"a":4,"cite":"ASC 230","rat":"Net income = $200,000 (change in retained earnings plus dividends); + depreciation $70,000 - AR increase $30,000 + inventory decrease $20,000 - prepaid increase $5,000 + AP increase $15,000 - taxes payable decrease $8,000 = $262,000.","ex":["Uses the change in retained earnings ($110,000) as net income, forgetting that dividends also reduced retained earnings.","Omits the $70,000 depreciation add-back, which is a noncash expense.","Subtracts the decrease in inventory. A decrease in inventory is a source of cash and is added.","Net income = $200,000 (change in retained earnings plus dividends); + depreciation $70,000 - AR increase $30,000 + inventory decrease $20,000 - prepaid increase $5,000 + AP increase $15,000 - taxes payable decrease $8,000 = $262,000."],"wt":["concept","concept","calc",""],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Net income = change in retained earnings + dividends; then adjust for noncash items and changes in operating accounts.","tb":[["Account","Dec 31, 2025","Dec 31, 2026"],["Accounts receivable","$130,000","$160,000"],["Inventory","$210,000","$190,000"],["Prepaid expenses","$15,000","$20,000"],["Accumulated depreciation","$300,000","$370,000"],["Accounts payable","$85,000","$100,000"],["Income taxes payable","$22,000","$14,000"],["Retained earnings","$500,000","$610,000"]],"from":"2026-01-01","calc":1,"steps":["Net income = 610,000 - 500,000 + 90,000 = 200,000","Depreciation = 370,000 - 300,000 = 70,000","200,000 + 70,000 - 30,000 + 20,000 - 5,000 + 15,000 - 8,000 = 262,000"]}},{"i":"FAR-I-A-0037","t":"Gross property and equipment of Crestline Inc. rose from $800,000 to $950,000 during 2026, and accumulated depreciation rose from $300,000 to $340,000. Depreciation expense was $65,000. Crestline sold equipment with a cost of $90,000 for $50,000 in cash, recognizing a $15,000 loss; there were no other disposals. What was net cash used in investing activities?","mc":{"s":"Gross property and equipment of Crestline Inc. rose from $800,000 to $950,000 during 2026, and accumulated depreciation rose from $300,000 to $340,000. Depreciation expense was $65,000. Crestline sold equipment with a cost of $90,000 for $50,000 in cash, recognizing a $15,000 loss; there were no other disposals. What was net cash used in investing activities?","d":"","o":["$100,000","$150,000","$190,000","$290,000"],"a":3,"cite":"ASC 230","rat":"Purchases = $950,000 - $800,000 + $90,000 cost of the disposal = $240,000; net investing = $240,000 - $50,000 proceeds = $190,000 used.","ex":["Computes purchases from the net change in gross equipment ($150,000), which ignores replacement of the $90,000 of equipment sold.","Nets the cost of the equipment sold ($90,000) instead of the cash proceeds ($50,000).","Purchases = $950,000 - $800,000 + $90,000 cost of the disposal = $240,000; net investing = $240,000 - $50,000 proceeds = $190,000 used.","Adds the sale proceeds to the purchases instead of netting them as an inflow."],"wt":["calc","calc","","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Purchases = ending gross asset - beginning gross asset + cost of assets disposed; sale proceeds are investing inflows.","from":"2026-01-01","calc":1,"steps":["Purchases 950000 - 800000 + 90000 = 240000","Net investing = -240000 + 50000 = -190000"]}},{"i":"FAR-I-A-0038","t":"Ivory Co. reported net income of $400,000, which included depreciation of $60,000 and $50,000 of equity in earnings of an investee. During the year Ivory received cash dividends of $20,000 from the investee. Ignoring other items, what is Ivory's net cash provided by operating activities using the indirect method?","mc":{"s":"Ivory Co. reported net income of $400,000, which included depreciation of $60,000 and $50,000 of equity in earnings of an investee. During the year Ivory received cash dividends of $20,000 from the investee. Ignoring other items, what is Ivory's net cash provided by operating activities using the indirect method?","d":"","o":["$390,000","$410,000","$430,000","$460,000"],"a":3,"cite":"ASC 230; ASC 323","rat":"$400,000 + depreciation $60,000 - equity earnings $50,000 + dividends received $20,000 = $430,000.","ex":["Subtracts the dividends. Dividends received from the investee are a cash inflow.","Removes the equity earnings but does not add the $20,000 dividends received.","$400,000 + depreciation $60,000 - equity earnings $50,000 + dividends received $20,000 = $430,000. Dividends received (up to earnings) are operating cash inflows.","Leaves the $50,000 noncash equity earnings in operating cash flow."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Deduct equity-method earnings as noncash and add dividends received; distributions up to cumulative earnings are operating.","from":"2026-01-01","calc":1,"steps":["400000 + 60000 - 50000 + 20000 = 430000"]}},{"i":"FAR-I-A-0039","t":"Quill Corp. had net income of $250,000 in 2026. It recorded amortization of bond discount of $12,000, amortization of bond premium of $8,000, deferred income tax expense of $20,000, stock-based compensation expense of $15,000, and an impairment loss of $40,000. Ignoring working capital changes, what is net cash provided by operating activities?","mc":{"s":"Quill Corp. had net income of $250,000 in 2026. It recorded amortization of bond discount of $12,000, amortization of bond premium of $8,000, deferred income tax expense of $20,000, stock-based compensation expense of $15,000, and an impairment loss of $40,000. Ignoring working capital changes, what is net cash provided by operating activities?","d":"","o":["$289,000","$309,000","$329,000","$345,000"],"a":3,"cite":"ASC 230","rat":"Add back noncash expenses (discount amortization, deferred tax, stock compensation, impairment) and subtract premium amortization: $329,000.","ex":["Omits the $40,000 impairment loss, which is a noncash charge to be added back.","Omits the $20,000 deferred income tax expense, which is noncash.","Add back noncash expenses (discount amortization, deferred tax, stock compensation, impairment) and subtract premium amortization: $329,000.","Adds premium amortization. Premium amortization reduces interest expense without cash, so it is subtracted."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Noncash expenses and losses are added back; amortization of bond premium and other noncash gains are subtracted.","from":"2026-01-01","calc":1,"steps":["250000 + 12000 - 8000 + 20000 + 15000 + 40000 = 329000"]}},{"i":"FAR-I-A-0040","t":"Using the direct method, Bolton Co. reported these 2026 operating cash flows: cash collected from customers $1,150,000; cash paid to suppliers $700,000; cash paid for operating expenses $280,000; interest paid $25,000; income taxes paid $60,000; and interest received $10,000. What is net cash provided by operating activities?","mc":{"s":"Using the direct method, Bolton Co. reported these 2026 operating cash flows: cash collected from customers $1,150,000; cash paid to suppliers $700,000; cash paid for operating expenses $280,000; interest paid $25,000; income taxes paid $60,000; and interest received $10,000. What is net cash provided by operating activities?","d":"","o":["$85,000","$95,000","$120,000","$155,000"],"a":2,"cite":"ASC 230","rat":"$1,150,000 - $700,000 - $280,000 - $25,000 - $60,000 + $10,000 = $95,000.","ex":["Omits the $10,000 interest received, which is an operating inflow.","$1,150,000 - $700,000 - $280,000 - $25,000 - $60,000 + $10,000 = $95,000.","Omits interest paid; interest paid is an operating outflow.","Omits the $60,000 income taxes paid, an operating outflow."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Direct-method operating cash flow includes interest and income taxes paid and interest received.","from":"2026-01-01","calc":1,"steps":["1150000 - 700000 - 280000 - 25000 - 60000 + 10000 = 95000"]}},{"i":"FAR-I-A-0041","t":"Sunbeam Co. sold equipment that cost $120,000 and had accumulated depreciation of $70,000 for $62,000 cash. Under the indirect method, what amount is reported for this sale as an investing inflow?","mc":{"s":"Sunbeam Co. sold equipment that cost $120,000 and had accumulated depreciation of $70,000 for $62,000 cash. Under the indirect method, what amount is reported for this sale as an investing inflow?","d":"","o":["$12,000","$50,000","$62,000","$120,000"],"a":3,"cite":"ASC 230","rat":"The investing inflow is the cash proceeds of $62,000; the $12,000 gain is subtracted in operating activities.","ex":["Reports the gain ($12,000) rather than the proceeds. The gain is a noncash adjustment.","Reports the carrying amount of $50,000, not the cash received.","The investing inflow is the cash proceeds of $62,000; the $12,000 gain is subtracted in operating activities.","Reports the original cost of $120,000; that amount is not cash received."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Investing inflows equal cash proceeds; the gain or loss is removed from operating cash flow under the indirect method.","from":"2026-01-01","calc":1,"steps":["Proceeds = 62000","Gain = 62000 - (120000 - 70000) = 12000 (subtracted in operating)"]}},{"i":"FAR-I-A-0042","t":"Sunrise Cabinetry, a private company, had these 2026 transactions. Which one is NOT required to be disclosed as a related party transaction?","mc":{"s":"Sunrise Cabinetry, a private company, had these 2026 transactions. Which one is NOT required to be disclosed as a related party transaction?","d":"","o":["Salary and expense allowances paid to the chief executive under her ordinary employment agreement","Sale of a warehouse to a company owned by the chief executive's spouse for less than fair value","A below-market loan made to a director, with the terms and balance outstanding at year-end","Purchases of materials from a supplier in which the board chair holds a significant ownership stake"],"a":1,"cite":"ASC 850","rat":"Compensation arrangements and expense allowances in the ordinary course of business are excluded from related party disclosure.","ex":["Compensation arrangements and expense allowances in the ordinary course of business are excluded from related party disclosure.","A sale to an entity controlled by a member of management's immediate family is a related party transaction to be disclosed.","Loans to directors are related party transactions and must be disclosed, including amounts due at year-end.","Transactions with an entity significantly influenced by a principal owner are related party transactions."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Disclose related party relationships, transaction nature and amounts; ordinary compensation and expense allowances are exempt.","from":"2026-01-01"}},{"i":"FAR-I-A-0043","t":"Wexford Farms sells 70% of its output to one grocery chain. In February 2027, before Wexford issued its 2026 statements, the chain announced it will move to another supplier beginning in six months. Wexford's sales to the chain were correctly recorded. What is the reporting consequence?","mc":{"s":"Wexford Farms sells 70% of its output to one grocery chain. In February 2027, before Wexford issued its 2026 statements, the chain announced it will move to another supplier beginning in six months. Wexford's sales to the chain were correctly recorded. What is the reporting consequence?","d":"","o":["No disclosure is needed, because the sales were properly recorded and the loss of the customer is a future event","Disclose only if the chain's accounts receivable at year-end were past due or considered uncollectible","Disclose only if the chain is a related party, since concentration risks are limited to related party dealings","Disclose the concentration, because it existed at the balance sheet date and it is reasonably possible its loss will cause a severe near-term impact"],"a":4,"cite":"ASC 275","rat":"Concentrations must be disclosed when they exist at the balance sheet date and events could reasonably cause a severe near-term impact.","ex":["Disclosure of concentrations is required in addition to proper recognition when a near-term severe impact is reasonably possible.","Disclosure does not depend on collectibility; the risk is vulnerability from the concentration.","Concentration disclosures apply to customers, suppliers and other sources regardless of relationship.","Concentrations must be disclosed when they exist at the balance sheet date and events could reasonably cause a severe near-term impact."],"wt":["concept","trap","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Disclose concentrations that exist at the balance sheet date and expose the entity to a reasonably possible severe near-term impact.","from":"2026-01-01"}},{"i":"FAR-I-A-0044","t":"Which condition must exist for an entity to disclose the nature of an uncertainty about an estimate in its financial statements?","mc":{"s":"Which condition must exist for an entity to disclose the nature of an uncertainty about an estimate in its financial statements?","d":"","o":["It is probable that the estimate will change in the next fiscal year, and the change would exceed the entity's income","It is remote that the estimate will change, but management wants to describe the process used to determine it","The estimate relates to a loss contingency that has been accrued and the amount is exactly determinable at year-end","It is at least reasonably possible that the estimate will change in the near term, and the effect of the change would be material"],"a":4,"cite":"ASC 275","rat":"Disclosure is required when a change in an estimate in the near term is at least reasonably possible and the effect would be material.","ex":["Probable is a higher threshold than needed, and there is no requirement that the effect exceed income.","Remote possibility does not trigger the required uncertainty disclosure.","An amount that is exactly determinable is not an estimate uncertain in the near term.","Disclosure is required when a change in an estimate in the near term is at least reasonably possible and the effect would be material."],"wt":["limit","concept","concept",""],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Disclose an estimate's uncertainty when a near-term change is at least reasonably possible and would be material.","from":"2026-01-01"}},{"i":"FAR-I-A-0045","t":"Pilgrim Freight prepares its statement of cash flows using the indirect method. In addition to noncash investing and financing activities, which amounts must it disclose?","mc":{"s":"Pilgrim Freight prepares its statement of cash flows using the indirect method. In addition to noncash investing and financing activities, which amounts must it disclose?","d":"","o":["Cash paid for interest, net of capitalized amounts, and cash paid for income taxes","Cash paid for payroll and cash paid for utilities, in total for the year","Cash paid for dividends and cash received from interest, stated separately","Cash paid for property additions and cash received from customers in the year"],"a":1,"cite":"ASC 230","rat":"Under the indirect method, cash paid for interest (excluding capitalized) and income taxes must be disclosed.","ex":["Under the indirect method, cash paid for interest (excluding capitalized) and income taxes must be disclosed.","These are not required disclosures; detail of other operating payments is not needed under the indirect method.","Dividends paid appear in financing; interest received is not among the required supplemental disclosures.","Property additions are in investing activities and customer receipts are a direct-method line item."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"With the indirect method, disclose interest paid (net of capitalized interest) and income taxes paid.","from":"2026-01-01"}},{"i":"FAR-I-A-0046","t":"At December 31, 2026, Corvin Corp. has long-term notes maturing as follows: 2027, $300,000; 2028, $500,000; 2029, $200,000; 2030, none; 2031, $1,000,000; 2032, $900,000. Which disclosure about maturities is required?","mc":{"s":"At December 31, 2026, Corvin Corp. has long-term notes maturing as follows: 2027, $300,000; 2028, $500,000; 2029, $200,000; 2030, none; 2031, $1,000,000; 2032, $900,000. Which disclosure about maturities is required?","d":"","o":["Only the total long-term debt of $2,900,000 together with its final maturity date","Only the $300,000 current portion, because the later maturities are classified as long-term","The amount maturing in each of the six years 2027 through 2032, shown separately","The amount maturing in each of the five years 2027 through 2031, shown separately"],"a":4,"cite":"ASC 470","rat":"Aggregate maturities and sinking fund requirements are disclosed for each of the five years after the balance sheet date.","ex":["A total is not enough; the five-year maturity schedule is required.","Later maturities must also be disclosed by year for the next five years.","The requirement covers five years; a sixth year is beyond it.","Aggregate maturities and sinking fund requirements are disclosed for each of the five years after the balance sheet date."],"wt":["concept","concept","limit",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Disclose combined maturities of long-term borrowings for each of the five years following the balance sheet date.","from":"2026-01-01"}}],"2":[{"i":"FAR-I-B-0001","t":"Riverside Community Center, a not-for-profit organization, is preparing its statement of financial position under current standards. Into which classes must it report net assets?","mc":{"s":"Riverside Community Center, a not-for-profit organization, is preparing its statement of financial position under current standards. Into which classes must it report net assets?","d":"","o":["Net assets without donor restrictions and net assets with donor restrictions","Unrestricted, temporarily restricted, and permanently restricted net assets","Operating, board-designated, and endowment net assets, whether or not donors restricted them","Current and noncurrent net assets, based on the year in which the resources will be used"],"a":1,"cite":"ASC 958","rat":"Current standards require two classes based on the presence or absence of donor-imposed restrictions.","ex":["Current standards require two classes based on the presence or absence of donor-imposed restrictions.","This three-class model was replaced by the two-class model; temporarily and permanently restricted are no longer required classes.","Board designations and endowments are subsets that may be disclosed, not the required classes.","Net assets are classified by donor restrictions, not by timing of use."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"B","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Not-for-profits report net assets in two classes: without donor restrictions and with donor restrictions.","from":"2026-01-01"}},{"i":"FAR-I-B-0002","t":"In 2026 the board of directors of Lakeshore Arts Society voted to set aside $2,000,000 of its general funds as an operating reserve. No donor placed any conditions on those funds. How should the reserve be classified?","mc":{"s":"In 2026 the board of directors of Lakeshore Arts Society voted to set aside $2,000,000 of its general funds as an operating reserve. No donor placed any conditions on those funds. How should the reserve be classified?","d":"","o":["Net assets without donor restrictions, with the board designation disclosed","Net assets with donor restrictions, because the money is set aside for a specific future use","A liability of $2,000,000, because the board has committed the entity to hold the funds for reserves","An appropriation reducing net assets without donor restrictions by the reserved portion, leaving none available"],"a":1,"cite":"ASC 958","rat":"Governing board designations are internal and do not create donor restrictions, so the funds stay without donor restrictions.","ex":["Governing board designations are internal and do not create donor restrictions, so the funds stay without donor restrictions.","Only donors and external parties can impose restrictions. The board's action is a voluntary designation.","A designation is not a present obligation to another party, so no liability arises.","Net assets are not reduced by a designation; it only affects disclosure."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Board designations do not create donor restrictions; designated funds remain net assets without donor restrictions.","from":"2026-01-01"}},{"i":"FAR-I-B-0003","t":"On December 31, 2026, a donor made an unconditional promise to give Hollis Foundation $100,000 at the end of each of the next three years (2027, 2028 and 2029) for general operations. Hollis uses a 6% discount rate for pledges. What contribution revenue should Hollis recognize in 2026?","mc":{"s":"On December 31, 2026, a donor made an unconditional promise to give Hollis Foundation $100,000 at the end of each of the next three years (2027, 2028 and 2029) for general operations. Hollis uses a 6% discount rate for pledges. What contribution revenue should Hollis recognize in 2026?","d":"","o":["$94,340","$267,301","$283,339","$300,000"],"a":2,"cite":"ASC 958","rat":"An unconditional promise is recognized at present value: $100,000 / 1.06 + $100,000 / 1.06^2 + $100,000 / 1.06^3 = $267,301.","ex":["Recognizes only the first installment's present value and ignores the later promised payments, which are also unconditional.","An unconditional promise is recognized at present value: $100,000 / 1.06 + $100,000 / 1.06^2 + $100,000 / 1.06^3 = $267,301.","Treats the first payment as received immediately (annuity due); the first installment is due one year out.","Recognizes the undiscounted total of $300,000. Multi-year unconditional promises are measured at present value."],"wt":["concept","","calc","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Unconditional promises to give are recognized as contributions when made, measured at present value of expected future cash flows.","from":"2026-01-01","calc":1,"steps":["Year 1: 100,000/1.06 = 94,339.62","Year 2: 100,000/1.06^2 = 88,999.64","Year 3: 100,000/1.06^3 = 83,961.93","Total = 267,301.19, rounded to $267,301"]}},{"i":"FAR-I-B-0004","t":"Cascade Health Center received a grant of up to $600,000 from a foundation to reimburse allowable costs of a wellness program; the foundation may recover unspent or misspent amounts. During 2026 the center incurred $220,000 of allowable program costs and received $150,000 in cash in advance. What grant revenue should the center recognize in 2026?","mc":{"s":"Cascade Health Center received a grant of up to $600,000 from a foundation to reimburse allowable costs of a wellness program; the foundation may recover unspent or misspent amounts. During 2026 the center incurred $220,000 of allowable program costs and received $150,000 in cash in advance. What grant revenue should the center recognize in 2026?","d":"","o":["$150,000","$220,000","$370,000","$600,000"],"a":2,"cite":"ASC 958","rat":"The grant is conditional (barrier plus right of return).","ex":["Recognizes the cash received. Advances on a conditional grant are refundable advances until the conditions are met.","The grant is conditional (barrier plus right of return). Revenue is recognized as qualifying costs are incurred: $220,000.","Adds the cash received to the costs incurred, double counting the amounts.","Recognizes the whole grant ceiling. The conditions are met only as costs are incurred."],"wt":["concept","","calc","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A conditional contribution, with a barrier and a right of return, is recognized only as the barrier is overcome.","from":"2026-01-01","calc":1,"steps":["Conditional grant: revenue recognized as allowable costs are incurred","Revenue 2026 = 220,000; advance of 150,000 is a refundable advance until costs are incurred"]}},{"i":"FAR-I-B-0005","t":"Northfield Symphony held a benefit gala. A corporation paid $10,000 for a table of ten, and the fair value of the dinner and entertainment its guests received was $3,000. What contribution revenue should Northfield recognize for this table?","mc":{"s":"Northfield Symphony held a benefit gala. A corporation paid $10,000 for a table of ten, and the fair value of the dinner and entertainment its guests received was $3,000. What contribution revenue should Northfield recognize for this table?","d":"","o":["$0","$3,000","$7,000","$10,000"],"a":3,"cite":"ASC 958","rat":"The $3,000 of benefit received is an exchange and only the excess of $7,000 is a contribution.","ex":["Recognizes no contribution because the guests received a meal; only the excess over the value received is a contribution.","Recognizes only the exchange portion as a contribution; the $3,000 is exchange revenue, not a contribution.","The $3,000 of benefit received is an exchange and only the excess of $7,000 is a contribution.","Treats the entire $10,000 as a contribution even though the donor received $3,000 of commensurate value."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"When a resource provider receives commensurate value, that part is an exchange; only the excess over fair value is a contribution.","from":"2026-01-01","calc":1,"steps":["Contribution = 10,000 - 3,000 = 7,000","Exchange revenue = 3,000"]}},{"i":"FAR-I-B-0006","t":"Greenway Alliance received 1,200 hours of accounting services from volunteer CPAs, valued at $60 per hour, which the organization would otherwise have purchased. It also received 3,000 hours of volunteer time from people stuffing envelopes, valued at $15 per hour. The stuffing work requires no specialized skills. What amount of contributed services revenue should Greenway recognize?","mc":{"s":"Greenway Alliance received 1,200 hours of accounting services from volunteer CPAs, valued at $60 per hour, which the organization would otherwise have purchased. It also received 3,000 hours of volunteer time from people stuffing envelopes, valued at $15 per hour. The stuffing work requires no specialized skills. What amount of contributed services revenue should Greenway recognize?","d":"","o":["$18,000","$45,000","$72,000","$117,000"],"a":3,"cite":"ASC 958","rat":"Only services requiring specialized skills that would otherwise be purchased are recognized: 1,200 x $60 = $72,000.","ex":["Values the CPA hours at the unskilled rate; the CPA hours should be measured at their fair value of $60.","Recognizes only the unskilled volunteer time. Services with no specialized skill are not recognized.","Only services requiring specialized skills that would otherwise be purchased are recognized: 1,200 x $60 = $72,000.","Recognizes both groups of services. Nonspecialized services do not meet the recognition criteria."],"wt":["calc","concept","","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Contributed services are recognized only if they create or enhance nonfinancial assets or require specialized skills that would otherwise be purchased.","from":"2026-01-01","calc":1,"steps":["Specialized CPA services: 1,200 hours x $60 = 72,000 recognized as revenue and expense","Envelope stuffing: not recognized"]}},{"i":"FAR-I-B-0007","t":"A museum received a donated painting that it will hold for public exhibition. The museum's policy prohibits selling collection items except to acquire other art, and requires any proceeds to be used only for acquiring collection items. Which treatment is permitted?","mc":{"s":"A museum received a donated painting that it will hold for public exhibition. The museum's policy prohibits selling collection items except to acquire other art, and requires any proceeds to be used only for acquiring collection items. Which treatment is permitted?","d":"","o":["Capitalize the painting at fair value and report contribution revenue with donor restrictions, without any policy disclosure","Capitalize the painting at the donor's original cost and report revenue without donor restrictions in the same period","Recognize the painting as revenue but do not report it as an asset, reporting a liability for the exhibition obligation","Do not capitalize the painting or recognize contribution revenue, and disclose the collection policy in the notes"],"a":4,"cite":"ASC 958","rat":"Collections meeting the three criteria may be excluded from the statements of financial position and activities, with note disclosure.","ex":["Capitalization is permitted but not required for such collections; note disclosure is required if it is not capitalized.","Contributions are measured at fair value, not the donor's cost.","No liability arises, and revenue without an asset is not a valid treatment.","Collections meeting the three criteria may be excluded from the statements of financial position and activities, with note disclosure."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Collection items held for exhibition and not sold except to buy other collection items need not be capitalized, but the policy is disclosed.","from":"2026-01-01"}},{"i":"FAR-I-B-0008","t":"For 2026, an endowment of Bright Futures Foundation earned dividends and interest of $60,000, realized gains of $25,000 and unrealized gains of $65,000. The foundation paid $12,000 of external investment management fees and incurred $8,000 of internal salary costs directly related to investment activities. What net investment return should be reported in the statement of activities?","mc":{"s":"For 2026, an endowment of Bright Futures Foundation earned dividends and interest of $60,000, realized gains of $25,000 and unrealized gains of $65,000. The foundation paid $12,000 of external investment management fees and incurred $8,000 of internal salary costs directly related to investment activities. What net investment return should be reported in the statement of activities?","d":"","o":["$65,000","$130,000","$138,000","$150,000"],"a":2,"cite":"ASC 958","rat":"Investment return is reported net of external and direct internal investment expenses: $150,000 - $12,000 - $8,000 = $130,000.","ex":["Excludes the unrealized gains from investment return; both realized and unrealized amounts are included.","Investment return is reported net of external and direct internal investment expenses: $150,000 - $12,000 - $8,000 = $130,000.","Deducts only external fees; direct internal investment expenses are also netted.","Reports return gross of all investment expenses; expenses are netted against return."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"B","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Investment return is reported net of external and direct internal investment expenses; realized and unrealized gains are both included.","from":"2026-01-01","calc":1,"steps":["Gross return = 60,000 + 25,000 + 65,000 = 150,000","Less external fees 12,000 and direct internal costs 8,000 = 130,000"]}},{"i":"FAR-I-B-0009","t":"A donor gave Westbrook Society $200,000 restricted to buying equipment. In 2026 Westbrook bought equipment for $200,000 and placed it in service; its useful life is 10 years and the donor set no other conditions on how long the asset must be used. What amount is released from restrictions in 2026?","mc":{"s":"A donor gave Westbrook Society $200,000 restricted to buying equipment. In 2026 Westbrook bought equipment for $200,000 and placed it in service; its useful life is 10 years and the donor set no other conditions on how long the asset must be used. What amount is released from restrictions in 2026?","d":"","o":["$0","$20,000","$180,000","$200,000"],"a":4,"cite":"ASC 958","rat":"Absent other donor stipulations, the restriction is met when the equipment is placed in service, so all $200,000 is released.","ex":["Records no release until the asset is fully depreciated; that approach was eliminated.","Releases only annual depreciation. The former implied time-restriction approach was eliminated.","Releases the carrying amount net of one year of depreciation, which has no support.","Absent other donor stipulations, the restriction is met when the equipment is placed in service, so all $200,000 is released."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A donor restriction on buying long-lived assets expires when the asset is placed in service, unless the donor sets other conditions.","from":"2026-01-01","calc":1,"steps":["Restriction on acquisition is met when placed in service in 2026","Release = 200,000"]}},{"i":"FAR-I-B-0010","t":"Health Alliance mailed a $100,000 brochure to a list of prior donors selected because of their ability and likelihood to give. The brochure devoted 60% of its space to heart-disease education and 40% to a request for donations. The mailing includes a call for action. What amount should Health Alliance report as fundraising expense?","mc":{"s":"Health Alliance mailed a $100,000 brochure to a list of prior donors selected because of their ability and likelihood to give. The brochure devoted 60% of its space to heart-disease education and 40% to a request for donations. The mailing includes a call for action. What amount should Health Alliance report as fundraising expense?","d":"","o":["$40,000","$50,000","$60,000","$100,000"],"a":4,"cite":"ASC 958","rat":"The audience was selected for likelihood to give, so the purpose criteria are not met and the entire $100,000 is fundraising.","ex":["Allocates by page space. Allocation is allowed only when the purpose, audience and content criteria are all met.","Splits the cost equally between program and fundraising, which is not a permitted method here.","Reports the educational share as fundraising, which reverses the allocation and still ignores the criteria.","The audience was selected for likelihood to give, so the purpose criteria are not met and the entire $100,000 is fundraising."],"wt":["concept","concept","calc",""],"tags":{"area":"I","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Joint costs may be allocated to program only if the purpose, audience and content criteria are met; otherwise all is fundraising.","from":"2026-01-01","calc":1,"steps":["Audience selected for ability to give fails the audience criterion","All 100,000 is fundraising expense"]}},{"i":"FAR-I-B-0011","t":"At December 31, 2026, Summit Learning Center held: cash of $300,000, of which $40,000 is restricted by donors for a specific program; receivables of $80,000 due within one year; and investments of $500,000, including a donor-restricted permanent endowment of $150,000 and a $100,000 investment in a private partnership that cannot be redeemed for three years. The remaining investments can be sold within a week. What amount of financial assets is available to meet general expenditures within one year?","mc":{"s":"At December 31, 2026, Summit Learning Center held: cash of $300,000, of which $40,000 is restricted by donors for a specific program; receivables of $80,000 due within one year; and investments of $500,000, including a donor-restricted permanent endowment of $150,000 and a $100,000 investment in a private partnership that cannot be redeemed for three years. The remaining investments can be sold within a week. What amount of financial assets is available to meet general expenditures within one year?","d":"","o":["$590,000","$630,000","$690,000","$880,000"],"a":1,"cite":"ASC 958","rat":"Available = ($300,000 - $40,000) + $80,000 + ($500,000 - $150,000 - $100,000) = $590,000.","ex":["Available = ($300,000 - $40,000) + $80,000 + ($500,000 - $150,000 - $100,000) = $590,000.","Includes the $40,000 restricted cash, which is not available for general expenditures.","Includes the $100,000 partnership interest, which cannot be converted to cash within a year.","Includes all financial assets regardless of donor restrictions or illiquidity."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Financial assets are not available for general expenditure within a year if donor-restricted or not convertible to cash within that period.","from":"2026-01-01","calc":1,"steps":["Cash 300,000 - restricted 40,000 = 260,000","Receivables 80,000","Investments 500,000 - endowment 150,000 - partnership 100,000 = 250,000","Total = 590,000"]}},{"i":"FAR-I-B-0012","t":"Harbor Community Foundation received $50,000 from a donor who instructed it to pass the money to Children's Shelter, an unrelated organization. Harbor has no variance power and the donor did not name Harbor as a beneficiary. How should Harbor report the transaction?","mc":{"s":"Harbor Community Foundation received $50,000 from a donor who instructed it to pass the money to Children's Shelter, an unrelated organization. Harbor has no variance power and the donor did not name Harbor as a beneficiary. How should Harbor report the transaction?","d":"","o":["As a liability to Children's Shelter of $50,000, with no contribution revenue","As contribution revenue without donor restrictions of $50,000, later reported as an expense on transfer","As contribution revenue with donor restrictions of $50,000, released upon transfer to Children's Shelter","As a refundable advance until Children's Shelter signs a receipt, then as revenue at that time"],"a":1,"cite":"ASC 958","rat":"Harbor acts as an agent.","ex":["Harbor acts as an agent. Assets held for another party without variance power create a liability, not revenue.","Revenue and expense are recognized only if the foundation has discretion (variance power) or is a beneficiary.","Agent-held assets are not the foundation's contribution revenue at all.","The intermediary does not recognize revenue on the later transfer; it only settles the liability."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An intermediary with no variance power that receives assets for an unrelated beneficiary reports a liability, not contribution revenue.","from":"2026-01-01"}},{"i":"FAR-I-B-0013","t":"Ridgeview Foundation has a donor-restricted endowment created with a $1,000,000 gift that must be held in perpetuity. After market declines the fund's fair value is $940,000. State law (UPMIFA) is in effect and the foundation has no other endowment. What amount is reported as net assets with donor restrictions for this endowment?","mc":{"s":"Ridgeview Foundation has a donor-restricted endowment created with a $1,000,000 gift that must be held in perpetuity. After market declines the fund's fair value is $940,000. State law (UPMIFA) is in effect and the foundation has no other endowment. What amount is reported as net assets with donor restrictions for this endowment?","d":"","o":["$60,000","$880,000","$940,000","$1,000,000"],"a":3,"cite":"ASC 958","rat":"The $60,000 deficiency reduces net assets with donor restrictions, so the class shows the fund's fair value of $940,000.","ex":["Reports only the deficiency amount, which is not the amount of net assets in the fund.","Deducts the $60,000 deficiency twice, once from the fund and once again in the net asset presentation.","The $60,000 deficiency reduces net assets with donor restrictions, so the class shows the fund's fair value of $940,000.","Reports the original gift amount. The deficiency must be reported as a reduction of net assets with donor restrictions."],"wt":["concept","calc","","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Deficiencies in donor-restricted endowments reduce net assets with donor restrictions, not net assets without donor restrictions.","from":"2026-01-01","calc":1,"steps":["Deficiency = 1,000,000 - 940,000 = 60,000","Net assets with donor restrictions = 940,000"]}},{"i":"FAR-I-B-0014","t":"Bayside Museum received $500,000 in cash from donors, restricted to a permanent endowment, and invested it in long-term securities. How should the receipt be classified in the museum's statement of cash flows?","mc":{"s":"Bayside Museum received $500,000 in cash from donors, restricted to a permanent endowment, and invested it in long-term securities. How should the receipt be classified in the museum's statement of cash flows?","d":"","o":["As an operating inflow, because contributions are reported as revenue in the statement of activities","As an investing inflow, because the money was invested immediately in long-term securities","As a noncash activity, because the gift was designated for endowment and was not spent","As a financing inflow, because the donor restricted the gift to long-term purposes"],"a":4,"cite":"ASC 230","rat":"Cash received from donors restricted for endowment or long-term purposes is a financing activity.","ex":["The revenue is not automatically operating; gifts restricted to endowment are financing.","The receipt from donors is not the acquisition or disposal of a long-term asset; the purchase is investing.","The gift was received in cash and is reported in the statement.","Cash received from donors restricted for endowment or long-term purposes is a financing activity."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Donor-restricted gifts for endowment or long-term asset purposes are financing inflows in the statement of cash flows.","from":"2026-01-01"}},{"i":"FAR-I-B-0015","t":"A donor gave Elmwood Mission stock with a fair value of $80,000 on the gift date; the donor's cost was $30,000. Elmwood sold the stock later for $85,000. How much contribution revenue did Elmwood recognize when it received the stock?","mc":{"s":"A donor gave Elmwood Mission stock with a fair value of $80,000 on the gift date; the donor's cost was $30,000. Elmwood sold the stock later for $85,000. How much contribution revenue did Elmwood recognize when it received the stock?","d":"","o":["$30,000","$80,000","$85,000","$115,000"],"a":2,"cite":"ASC 958","rat":"A contribution is measured at fair value on the gift date: $80,000.","ex":["Uses the donor's cost. Contributions are measured at fair value.","A contribution is measured at fair value on the gift date: $80,000. The $5,000 later gain is reported separately as an investment gain.","Uses the later sale price. The subsequent gain arises after receipt and is not part of the contribution.","Adds unrelated amounts together and double counts the donor's cost and the later gain."],"wt":["concept","","concept","calc"],"tags":{"area":"I","group":"B","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Contributions of noncash assets are recorded at fair value at the date of the gift.","from":"2026-01-01","calc":1,"steps":["Revenue at receipt = fair value 80,000","Later gain = 85,000 - 80,000 = 5,000"]}},{"i":"FAR-I-B-0016","t":"Pine Valley Outreach paid $120,000 of rent for shared space. Its policy allocates rent by square footage: 60% program services, 25% management and general, and 15% fundraising. What amount of rent is reported as management and general expense?","mc":{"s":"Pine Valley Outreach paid $120,000 of rent for shared space. Its policy allocates rent by square footage: 60% program services, 25% management and general, and 15% fundraising. What amount of rent is reported as management and general expense?","d":"","o":["$18,000","$30,000","$72,000","$90,000"],"a":2,"cite":"ASC 958","rat":"Management and general = $120,000 x 25% = $30,000.","ex":["Uses the fundraising percentage of 15%.","Management and general = $120,000 x 25% = $30,000.","Uses the program services percentage of 60%.","Adds program and fundraising percentages (75%), the complement of management and general."],"wt":["calc","","calc","calc"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Shared costs are allocated to program and supporting service functions using a reasonable, consistently applied basis.","from":"2026-01-01","calc":1,"steps":["120,000 x 25% = 30,000"]}},{"i":"FAR-I-B-0017","t":"Total expenses of Quarry Lane Charities were $1,000,000: program services $780,000, management and general $130,000, and fundraising $90,000. What percentage of total expenses was spent on program services?","mc":{"s":"Total expenses of Quarry Lane Charities were $1,000,000: program services $780,000, management and general $130,000, and fundraising $90,000. What percentage of total expenses was spent on program services?","d":"","o":["22.0%","78.0%","85.7%","89.7%"],"a":2,"cite":"ASC 958","rat":"$780,000 / $1,000,000 = 78.0%.","ex":["Computes the supporting services share, not the program share.","$780,000 / $1,000,000 = 78.0%.","Leaves fundraising expenses out of the denominator.","Leaves management and general expenses out of the denominator."],"wt":["concept","","calc","calc"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Program service ratio = program expenses divided by total expenses.","from":"2026-01-01","calc":1,"steps":["Total = 780000+130000+90000 = 1000000","Ratio = 780000/1000000 = 78.0%"]}},{"i":"FAR-I-B-0018","t":"During 2026, Meadow Arts received: (a) an unconditional promise of $200,000 for general use, payable in 2027; (b) $150,000 in cash restricted to a youth program, of which $90,000 was spent on that program in 2026; and (c) a $300,000 promise that is conditional on Meadow Arts raising matching funds, which it has not yet raised. Ignore discounting. By how much did net assets with donor restrictions increase in 2026?","mc":{"s":"During 2026, Meadow Arts received: (a) an unconditional promise of $200,000 for general use, payable in 2027; (b) $150,000 in cash restricted to a youth program, of which $90,000 was spent on that program in 2026; and (c) a $300,000 promise that is conditional on Meadow Arts raising matching funds, which it has not yet raised. Ignore discounting. By how much did net assets with donor restrictions increase in 2026?","d":"","o":["$60,000","$260,000","$350,000","$560,000"],"a":2,"cite":"ASC 958","rat":"Time-restricted pledge $200,000 plus purpose-restricted gift $150,000 less $90,000 released = $260,000.","ex":["Omits the $200,000 unconditional pledge, which is recognized when made with a time restriction.","Time-restricted pledge $200,000 plus purpose-restricted gift $150,000 less $90,000 released = $260,000. The conditional promise is not recognized.","Does not deduct the $90,000 released from restriction when the program spending occurred.","Includes the $300,000 conditional promise. It is not recognized until the match is met."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Unconditional promises payable in the future carry a time restriction; conditional promises are not recognized until the condition is met.","from":"2026-01-01","calc":1,"steps":["Pledge (a) recognized: +200,000 with donor restrictions (time)","(b) +150,000 less 90,000 released = +60,000","(c) not recognized","Increase = 260,000"]}},{"i":"FAR-I-B-0019","t":"Which of the following is required for every not-for-profit organization's financial statements?","mc":{"s":"Which of the following is required for every not-for-profit organization's financial statements?","d":"","o":["An analysis of expenses by both natural and functional classification, in a separate statement, in the notes, or on the statement of activities","A separate statement of functional expenses, required only for voluntary health and welfare organizations","Classification of expenses by function only, with natural classification optional for all entities","A classified statement of financial position separating current from noncurrent assets and liabilities"],"a":1,"cite":"ASC 958","rat":"All not-for-profits must present expenses by both nature and function, and disclose the allocation methods.","ex":["All not-for-profits must present expenses by both nature and function, and disclose the allocation methods.","The analysis is required of all not-for-profits; the presentation location can vary.","Both natural and functional classifications are needed for all not-for-profits.","A classified statement of financial position is not required; information about liquidity is required instead."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"B","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"All not-for-profits present expenses by natural and functional classification and disclose liquidity and availability of financial assets.","from":"2026-01-01"}},{"i":"FAR-I-B-0020","t":"In March 2026 a donor gave Willow Camp $50,000 restricted to a summer camp session held in July 2026. Willow Camp spent the money as intended by August 2026. Willow Camp's policy is to report donor-restricted contributions whose restrictions are met in the same reporting period as revenue without donor restrictions, and it applies the policy consistently. How is the gift reported in the 2026 statement of activities?","mc":{"s":"In March 2026 a donor gave Willow Camp $50,000 restricted to a summer camp session held in July 2026. Willow Camp spent the money as intended by August 2026. Willow Camp's policy is to report donor-restricted contributions whose restrictions are met in the same reporting period as revenue without donor restrictions, and it applies the policy consistently. How is the gift reported in the 2026 statement of activities?","d":"","o":["As $50,000 of revenue with donor restrictions, followed by $50,000 of net assets released from restrictions","As $50,000 of deferred revenue reported as a liability until the camp session was completed","As $50,000 of revenue without donor restrictions, with an equal expense reclassification to program services","As $50,000 of revenue without donor restrictions, with no release from restrictions reported"],"a":4,"cite":"ASC 958","rat":"Under the policy election, the gift goes straight to net assets without donor restrictions since the restriction was met in the same period.","ex":["This is the required treatment only if the entity does not elect the policy; here the policy applies.","A gift with a purpose restriction is not a liability; the restriction affects the net asset class.","The expense is recognized when the cost is incurred, not as a reclassification of the gift.","Under the policy election, the gift goes straight to net assets without donor restrictions since the restriction was met in the same period."],"wt":["trap","concept","concept",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A policy election lets restrictions met in the same period as receipt be reported directly in net assets without donor restrictions.","from":"2026-01-01"}}],"3":[{"i":"FAR-I-C-0001","t":"Which combination makes up the basic financial statements of a general-purpose state or local government?","mc":{"s":"Which combination makes up the basic financial statements of a general-purpose state or local government?","d":"","o":["Government-wide financial statements, fund financial statements, and notes to the financial statements","Management's discussion and analysis, a budgetary comparison schedule, and notes to the financial statements","Fund financial statements and combining statements for every nonmajor fund, with no government-wide statements","Government-wide financial statements and a schedule of expenditures of federal awards, without fund statements"],"a":1,"cite":"GASB 34","rat":"The basic financial statements consist of government-wide statements, fund statements and the notes.","ex":["The basic financial statements consist of government-wide statements, fund statements and the notes.","MD&A and the budgetary comparison schedule are required supplementary information, not basic financial statements.","Government-wide statements are required, and combining nonmajor fund statements are optional supplementary information.","Fund financial statements are required, and the federal awards schedule is a separate compliance requirement."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Basic financial statements = government-wide statements + fund statements + notes; MD&A and budgetary comparisons are required supplementary information.","from":"2026-01-01"}},{"i":"FAR-I-C-0002","t":"Which measurement focus and basis of accounting are used in the fund financial statements for governmental funds?","mc":{"s":"Which measurement focus and basis of accounting are used in the fund financial statements for governmental funds?","d":"","o":["Economic resources measurement focus and the accrual basis, with capital assets and long-term debt reported in each fund","Economic resources measurement focus and the modified accrual basis, with depreciation reported by each fund","Current financial resources measurement focus and the full accrual basis, with revenue recognized when earned","Current financial resources measurement focus and the modified accrual basis"],"a":4,"cite":"GASB 34","rat":"Governmental funds use current financial resources and modified accrual.","ex":["This is used for government-wide, proprietary and fiduciary statements, not governmental funds.","Depreciation and long-term items are reported under economic resources with full accrual, a combination not used.","Modified accrual, not full accrual, is the basis paired with current financial resources.","Governmental funds use current financial resources and modified accrual."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Governmental funds use current financial resources and modified accrual; proprietary, fiduciary and government-wide statements use economic resources and accrual.","from":"2026-01-01"}},{"i":"FAR-I-C-0003","t":"A city operates a fleet maintenance service that charges city departments on a cost-reimbursement basis and serves no external customers. The service is accounted for in an internal service fund. In the government-wide statement of net position, where are the internal service fund's assets and liabilities generally reported?","mc":{"s":"A city operates a fleet maintenance service that charges city departments on a cost-reimbursement basis and serves no external customers. The service is accounted for in an internal service fund. In the government-wide statement of net position, where are the internal service fund's assets and liabilities generally reported?","d":"","o":["In governmental activities, because the fund serves primarily the governmental funds","In business-type activities, because it is a proprietary fund using the economic resources measurement focus","In a separate column for fiduciary activities, because the assets are held on behalf of city departments","They are omitted from the government-wide statements because interfund charges are eliminated completely"],"a":1,"cite":"GASB 34","rat":"Internal service funds that primarily serve governmental activities are consolidated into governmental activities.","ex":["Internal service funds that primarily serve governmental activities are consolidated into governmental activities.","Internal service funds that serve governmental funds are included in governmental activities.","Fiduciary activities are not reported in the government-wide statements at all.","Balances are consolidated, with internal activity eliminated; the fund's assets and liabilities are still reported."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Internal service funds are proprietary funds; those serving mainly governmental funds are consolidated into governmental activities in government-wide statements.","from":"2026-01-01"}},{"i":"FAR-I-C-0004","t":"Which governmental fund type accounts for the proceeds of specific revenue sources that are legally restricted or committed to expenditure for specified purposes, other than debt service or major capital projects?","mc":{"s":"Which governmental fund type accounts for the proceeds of specific revenue sources that are legally restricted or committed to expenditure for specified purposes, other than debt service or major capital projects?","d":"","o":["Permanent fund","Enterprise fund","Internal service fund","Special revenue fund"],"a":4,"cite":"GASB 54","rat":"Special revenue funds report revenue sources restricted or committed for specified purposes, aside from debt service and capital projects.","ex":["Permanent funds report resources restricted so only earnings, not principal, benefit government programs.","Enterprise funds are proprietary funds for fee-based business-type activities, not governmental funds.","Internal service funds account for cost-reimbursement services to other departments, and are proprietary funds.","Special revenue funds report revenue sources restricted or committed for specified purposes, aside from debt service and capital projects."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Special revenue funds account for revenue sources legally restricted or committed to specified purposes other than debt service or major capital projects.","from":"2026-01-01"}},{"i":"FAR-I-C-0005","t":"Ashland County's governmental funds and enterprise funds have total revenues shown in the exhibit. The general fund is always major. Ashland has not elected to report any other fund as major, and assume total revenues is the only element that could make any fund major. Which other funds must be reported as major funds?","mc":{"s":"Ashland County's governmental funds and enterprise funds have total revenues shown in the exhibit. The general fund is always major. Ashland has not elected to report any other fund as major, and assume total revenues is the only element that could make any fund major. Which other funds must be reported as major funds?","d":"","o":["Special Revenue A and Capital Projects C","Capital Projects C and Debt Service D","Capital Projects C only","Special Revenue A, Special Revenue B and Capital Projects C"],"a":3,"cite":"GASB Statement 34, paragraph 76","rat":"Capital Projects C is at least 10% of governmental funds ($4.0M) and at least 5% of the combined total ($5.0M).","ex":["Special Revenue A ($4.5M) meets the 10% test of governmental funds but falls short of 5% of the governmental and enterprise total ($5.0M).","Debt Service D ($2.0M) is only 5% of governmental revenue; it fails the 10% test.","Capital Projects C is at least 10% of governmental funds ($4.0M) and at least 5% of the combined total ($5.0M). Special Revenue A meets 10% but not 5%.","Special Revenue B ($1.5M) is far below both tests, and A misses the 5% test."],"wt":["trap","limit","","limit"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A governmental fund is major if it meets 10% of its fund category and 5% of governmental and enterprise funds combined.","tb":[["Fund","Total revenues"],["General fund","$26,000,000"],["Special Revenue A","$4,500,000"],["Special Revenue B","$1,500,000"],["Capital Projects C","$6,000,000"],["Debt Service D","$2,000,000"],["All enterprise funds combined","$60,000,000"]],"from":"2026-01-01"}},{"i":"FAR-I-C-0006","t":"Baxter Township levied property taxes of $4,000,000 for 2026, of which it estimates $40,000 will be uncollectible. Baxter collected $3,600,000 during 2026 and $250,000 in the first 45 days of 2027. The township considers revenues available if collected within 60 days after year-end. The remaining net receivable is expected to be collected later in 2027. What property tax revenue should the general fund report for 2026?","mc":{"s":"Baxter Township levied property taxes of $4,000,000 for 2026, of which it estimates $40,000 will be uncollectible. Baxter collected $3,600,000 during 2026 and $250,000 in the first 45 days of 2027. The township considers revenues available if collected within 60 days after year-end. The remaining net receivable is expected to be collected later in 2027. What property tax revenue should the general fund report for 2026?","d":"","o":["$3,600,000","$3,850,000","$3,960,000","$4,000,000"],"a":2,"cite":"GASB 33; GASB 34","rat":"Revenue is recognized to the extent measurable and available: $3,600,000 + $250,000 = $3,850,000.","ex":["Recognizes only cash collected during the year, missing the amount collected within the availability period.","Revenue is recognized to the extent measurable and available: $3,600,000 + $250,000 = $3,850,000. The rest is a deferred inflow.","Recognizes the entire net levy, as under full accrual; the governmental fund also requires availability.","Recognizes the gross levy; uncollectible amounts are not measurable revenue."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Governmental funds recognize property tax revenue when measurable and available, generally collected within 60 days after year-end.","from":"2026-01-01","calc":1,"steps":["Collected in year 3600000","Collected within 60 days after year-end 250000","Revenue = 3850000"]}},{"i":"FAR-I-C-0007","t":"Baxter Township levied property taxes of $4,000,000 for 2026, estimating $40,000 to be uncollectible. It collected $3,600,000 in 2026 and $250,000 within the first 45 days of 2027. It considers revenues available if collected within 60 days after year-end. The remaining net receivable is expected to be collected in mid-2027. What deferred inflow of resources (unavailable revenue) does the general fund report at December 31, 2026?","mc":{"s":"Baxter Township levied property taxes of $4,000,000 for 2026, estimating $40,000 to be uncollectible. It collected $3,600,000 in 2026 and $250,000 within the first 45 days of 2027. It considers revenues available if collected within 60 days after year-end. The remaining net receivable is expected to be collected in mid-2027. What deferred inflow of resources (unavailable revenue) does the general fund report at December 31, 2026?","d":"","o":["$40,000","$110,000","$250,000","$360,000"],"a":2,"cite":"GASB 65; GASB 33","rat":"Net receivable $360,000 less the $250,000 available is $110,000, which is not available and is deferred.","ex":["Uses the uncollectible estimate, which is not deferred; it reduces the receivable.","Net receivable $360,000 less the $250,000 available is $110,000, which is not available and is deferred.","Uses the amount collected within the availability period, which is recognized as revenue, not deferred.","Defers the entire net receivable and ignores the amount collected in the first 45 days of 2027."],"wt":["concept","","concept","calc"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Property taxes receivable not available within the availability period are reported as deferred inflows in governmental funds.","from":"2026-01-01","calc":1,"steps":["Net receivable = 4000000 - 40000 - 3600000 = 360000","Deferred inflow = 360000 - 250000 = 110000"]}},{"i":"FAR-I-C-0008","t":"During 2026 the general fund of Corbin City paid salaries of $1,200,000, supplies of $300,000, $250,000 for new equipment, $400,000 of principal and $120,000 of interest on general obligation bonds (the city does not use a debt service fund). Depreciation on general capital assets was $90,000, and the liability for compensated absences not payable from current resources increased $30,000. What total expenditures should the general fund report?","mc":{"s":"During 2026 the general fund of Corbin City paid salaries of $1,200,000, supplies of $300,000, $250,000 for new equipment, $400,000 of principal and $120,000 of interest on general obligation bonds (the city does not use a debt service fund). Depreciation on general capital assets was $90,000, and the liability for compensated absences not payable from current resources increased $30,000. What total expenditures should the general fund report?","d":"","o":["$1,870,000","$2,270,000","$2,360,000","$2,390,000"],"a":2,"cite":"GASB 34","rat":"Expenditures include operating costs, capital outlay and debt service: $2,270,000.","ex":["Omits the $400,000 principal payment, which is a debt service expenditure in a governmental fund.","Expenditures include operating costs, capital outlay and debt service: $2,270,000. Depreciation and unmatured compensated absences are not expenditures.","Adds depreciation of $90,000, a noncash expense not recorded in governmental funds.","Adds depreciation and the $30,000 increase in long-term compensated absences, neither of which uses current financial resources."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Governmental funds record capital outlay and debt service as expenditures; depreciation and long-term accruals are not recognized.","from":"2026-01-01","calc":1,"steps":["1200000 + 300000 + 250000 + 400000 + 120000 = 2270000"]}},{"i":"FAR-I-C-0009","t":"In December 2026 the general fund of Dunmore Village issued purchase orders totaling $80,000 for supplies. By December 31, $60,000 of the supplies (order price) had been received and were invoiced at $62,000. The other $20,000 of supplies had not been received. What amount is reported as 2026 expenditures for these purchases?","mc":{"s":"In December 2026 the general fund of Dunmore Village issued purchase orders totaling $80,000 for supplies. By December 31, $60,000 of the supplies (order price) had been received and were invoiced at $62,000. The other $20,000 of supplies had not been received. What amount is reported as 2026 expenditures for these purchases?","d":"","o":["$60,000","$62,000","$80,000","$82,000"],"a":2,"cite":"GASB Cod. Sec. 1700","rat":"Expenditures are recorded at the invoice price when goods are received: $62,000.","ex":["Uses the purchase order price for the goods received; the actual invoice governs.","Expenditures are recorded at the invoice price when goods are received: $62,000. The $20,000 outstanding encumbrance is not an expenditure.","Recognizes all purchase orders as expenditures, although $20,000 of goods was not received.","Adds the outstanding encumbrance to the invoiced amount, which double counts the undelivered goods."],"wt":["calc","","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An encumbrance is a commitment, not an expenditure; expenditures are recorded when goods or services are received at actual cost.","from":"2026-01-01","calc":1,"steps":["Received goods invoiced at 62,000 = expenditure","Outstanding 20,000 stays an encumbrance, disclosed within committed or assigned fund balance"]}},{"i":"FAR-I-C-0010","t":"At December 31, 2026, the general fund of Harlan Borough had a total fund balance of $640,000. It includes inventory of $30,000; a state grant of $100,000 legally restricted to school programs; $250,000 committed to road resurfacing by ordinance of the borough council (its highest decision-making body); and $60,000 that the borough manager, authorized by council policy, earmarked for a computer purchase. What amount is reported as unassigned fund balance?","mc":{"s":"At December 31, 2026, the general fund of Harlan Borough had a total fund balance of $640,000. It includes inventory of $30,000; a state grant of $100,000 legally restricted to school programs; $250,000 committed to road resurfacing by ordinance of the borough council (its highest decision-making body); and $60,000 that the borough manager, authorized by council policy, earmarked for a computer purchase. What amount is reported as unassigned fund balance?","d":"","o":["$200,000","$230,000","$260,000","$450,000"],"a":1,"cite":"GASB 54","rat":"Unassigned = $640,000 - $30,000 nonspendable - $100,000 restricted - $250,000 committed - $60,000 assigned = $200,000.","ex":["Unassigned = $640,000 - $30,000 nonspendable - $100,000 restricted - $250,000 committed - $60,000 assigned = $200,000.","Treats the $30,000 inventory as spendable. Inventory is nonspendable.","Treats the $60,000 earmarked by the manager as unassigned, but intent expressed by an authorized official is assigned.","Treats the $250,000 committed by ordinance as unassigned, but formal action makes it committed."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Fund balance is nonspendable, restricted, committed, assigned or unassigned; only the residual is unassigned.","from":"2026-01-01","calc":1,"steps":["640000 - 30000 - 100000 - 250000 - 60000 = 200000"]}},{"i":"FAR-I-C-0011","t":"The city council of Marlow, the government's highest decision-making authority, passed an ordinance setting aside $500,000 of general fund resources for a future library expansion. The ordinance can be changed or removed only by another ordinance of the council. How should the $500,000 be classified in the general fund balance?","mc":{"s":"The city council of Marlow, the government's highest decision-making authority, passed an ordinance setting aside $500,000 of general fund resources for a future library expansion. The ordinance can be changed or removed only by another ordinance of the council. How should the $500,000 be classified in the general fund balance?","d":"","o":["Restricted fund balance, because the council's ordinance is a legally binding restriction on how the resources can be used","Assigned fund balance, because the council has expressed an intent to use the resources for the library expansion","Unassigned fund balance, because the general fund may retain only unassigned amounts once resources are earmarked","Committed fund balance, because the highest decision-making authority took formal action that binds the use of the resources"],"a":4,"cite":"GASB 54","rat":"A formal action of the highest authority that can be reversed only by the same action creates a commitment.","ex":["Restrictions come from external parties or law, not from the government's own decisions.","Assigned amounts reflect intent that is not a formal binding action of the highest body; this is a formal binding action.","Committed amounts may be reported in the general fund; they are not unassigned.","A formal action of the highest authority that can be reversed only by the same action creates a commitment."],"wt":["concept","trap","concept",""],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Committed fund balance requires formal action by the highest decision-making authority that can be changed only by the same action.","from":"2026-01-01"}},{"i":"FAR-I-C-0012","t":"The general fund of Tilden City transferred $200,000 to the capital projects fund to help finance a new fire station; the transfer is not a repayment or reimbursement. How should the general fund report the $200,000 in its statement of revenues, expenditures and changes in fund balance?","mc":{"s":"The general fund of Tilden City transferred $200,000 to the capital projects fund to help finance a new fire station; the transfer is not a repayment or reimbursement. How should the general fund report the $200,000 in its statement of revenues, expenditures and changes in fund balance?","d":"","o":["As an other financing use (transfer out)","As an expenditure for capital outlay","As a reduction of general fund revenues in the period","As an interfund receivable from the capital projects fund"],"a":1,"cite":"GASB 34","rat":"Transfers between funds are other financing sources and uses, reported after the excess of revenues over expenditures.","ex":["Transfers between funds are other financing sources and uses, reported after the excess of revenues over expenditures.","The general fund is not buying the asset; the capital projects fund incurs the construction expenditures.","A transfer is not a reduction of revenue; revenues are unaffected.","A receivable exists only if repayment is expected; this is a nonreciprocal transfer."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Nonreciprocal interfund transfers are reported as other financing uses in the paying fund and other financing sources in the receiving fund.","from":"2026-01-01"}},{"i":"FAR-I-C-0013","t":"During 2026, the general fund of Radnor City paid $30,000 of expenditures that belonged to the water enterprise fund, which repaid the general fund in full before year-end. How is the repayment reported?","mc":{"s":"During 2026, the general fund of Radnor City paid $30,000 of expenditures that belonged to the water enterprise fund, which repaid the general fund in full before year-end. How is the repayment reported?","d":"","o":["As a reduction of the general fund's expenditures and an expense of the enterprise fund","As an interfund transfer, an other financing use of the enterprise fund and a source of the general fund","As revenue of the general fund and an expense of the enterprise fund, reported gross in both funds","As a loan from the enterprise fund to the general fund, reported as an interfund payable"],"a":1,"cite":"GASB 34","rat":"A reimbursement of expenditures made for another fund is reported as an expenditure or expense in the fund that owns the cost and a reduction in the paying fund.","ex":["A reimbursement of expenditures made for another fund is reported as an expenditure or expense in the fund that owns the cost and a reduction in the paying fund.","Transfers are nonreciprocal; a reimbursement is not a transfer.","A reimbursement is not revenue; it reverses the general fund's expenditure.","The general fund was repaid, so no loan exists."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Reimbursements are recorded as expenditures or expenses in the fund that owns the cost and as reductions of expenditures in the fund that paid.","from":"2026-01-01"}},{"i":"FAR-I-C-0014","t":"Salem City issued general obligation bonds with a face amount of $5,000,000 for $5,100,000 (a premium of $100,000) to finance a new library. The city paid debt issuance costs of $45,000 from the proceeds and deposited the balance in its capital projects fund. Before any construction spending, what is the effect of the issuance on the capital projects fund balance?","mc":{"s":"Salem City issued general obligation bonds with a face amount of $5,000,000 for $5,100,000 (a premium of $100,000) to finance a new library. The city paid debt issuance costs of $45,000 from the proceeds and deposited the balance in its capital projects fund. Before any construction spending, what is the effect of the issuance on the capital projects fund balance?","d":"","o":["$5,000,000","$5,055,000","$5,100,000","$5,145,000"],"a":2,"cite":"GASB 34; GASB 65","rat":"Proceeds of $5,100,000 (face and premium) are other financing sources and issuance costs of $45,000 are expenditures: net increase $5,055,000.","ex":["Ignores both the premium and the issuance costs, reporting only face value.","Proceeds of $5,100,000 (face and premium) are other financing sources and issuance costs of $45,000 are expenditures: net increase $5,055,000.","Ignores the issuance costs. Debt issuance costs are expenditures in governmental funds.","Adds the issuance costs. They are paid out, reducing the fund balance."],"wt":["concept","","concept","calc"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Bond proceeds and premium are other financing sources in governmental funds; debt issuance costs are expenditures.","from":"2026-01-01","calc":1,"steps":["Other financing sources = 5000000 + 100000 = 5100000","Expenditures for issuance costs = 45000","Net = 5055000"]}},{"i":"FAR-I-C-0015","t":"Total governmental fund balances of Yates County are $6,000,000. The county also has capital assets, net of accumulated depreciation, of $22,000,000; bonds payable (including premium) of $9,000,000; accrued interest payable of $120,000; compensated absences of $300,000; and $110,000 of unavailable property tax revenue that is a deferred inflow in the funds but is revenue on the full accrual basis. The fund-level statements do not reflect any of these items. What is net position of governmental activities?","mc":{"s":"Total governmental fund balances of Yates County are $6,000,000. The county also has capital assets, net of accumulated depreciation, of $22,000,000; bonds payable (including premium) of $9,000,000; accrued interest payable of $120,000; compensated absences of $300,000; and $110,000 of unavailable property tax revenue that is a deferred inflow in the funds but is revenue on the full accrual basis. The fund-level statements do not reflect any of these items. What is net position of governmental activities?","d":"","o":["$18,470,000","$18,580,000","$18,690,000","$18,880,000"],"a":3,"cite":"GASB 34","rat":"Add capital assets, subtract long-term debt and accruals, and add the $110,000 revenue that was deferred in the funds: $18,690,000.","ex":["Subtracts the deferred inflow instead of adding it back.","Omits the $110,000 of revenue that is recognized under full accrual. Deferred inflows in funds are added back.","Add capital assets, subtract long-term debt and accruals, and add the $110,000 revenue that was deferred in the funds: $18,690,000.","Omits the $300,000 compensated absences, a long-term liability reported government-wide."],"wt":["calc","concept","","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Fund balance + capital assets - long-term liabilities - accrued interest + unavailable revenue = government-wide net position.","from":"2026-01-01","calc":1,"steps":["6000000 + 22000000 = 28000000","- 9000000 - 120000 - 300000 = 18580000","+ 110000 = 18690000"]}},{"i":"FAR-I-C-0016","t":"Governmental funds of Wade County reported expenditures of $8,000,000, which included capital outlay of $1,500,000 and principal repayments of $600,000. Depreciation for the year was $900,000, the liability for compensated absences increased $40,000, and accrued interest payable increased $15,000. What expenses are reported for governmental activities in the statement of activities, considering only these items?","mc":{"s":"Governmental funds of Wade County reported expenditures of $8,000,000, which included capital outlay of $1,500,000 and principal repayments of $600,000. Depreciation for the year was $900,000, the liability for compensated absences increased $40,000, and accrued interest payable increased $15,000. What expenses are reported for governmental activities in the statement of activities, considering only these items?","d":"","o":["$5,955,000","$6,855,000","$7,455,000","$8,355,000"],"a":2,"cite":"GASB 34","rat":"$8,000,000 - $1,500,000 capital outlay - $600,000 principal + $900,000 depreciation + $40,000 + $15,000 = $6,855,000.","ex":["Omits depreciation of $900,000, which is recognized on the full accrual basis.","$8,000,000 - $1,500,000 capital outlay - $600,000 principal + $900,000 depreciation + $40,000 + $15,000 = $6,855,000.","Leaves the $600,000 principal repayments in expenses; principal reduces the liability rather than being an expense.","Leaves capital outlay in expenses; on the full accrual basis it is capitalized, not expensed."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Convert expenditures to expenses: remove capital outlay and principal; add depreciation and net increases in long-term accruals.","from":"2026-01-01","calc":1,"steps":["8000000 - 1500000 - 600000 = 5900000","+ 900000 + 40000 + 15000 = 6855000"]}},{"i":"FAR-I-C-0017","t":"Kimball City's public safety function had expenses of $900,000 in 2026. It earned charges for services of $120,000, received operating grants of $80,000 for the function, and received capital grants of $50,000 restricted to public safety facilities. The city also collected general property taxes of $2,000,000. What is the net (expense) revenue for public safety in the statement of activities?","mc":{"s":"Kimball City's public safety function had expenses of $900,000 in 2026. It earned charges for services of $120,000, received operating grants of $80,000 for the function, and received capital grants of $50,000 restricted to public safety facilities. The city also collected general property taxes of $2,000,000. What is the net (expense) revenue for public safety in the statement of activities?","d":"","o":["$650,000","$700,000","$780,000","$900,000"],"a":1,"cite":"GASB 34","rat":"Net expense = $900,000 - $120,000 - $80,000 - $50,000 = $650,000.","ex":["Net expense = $900,000 - $120,000 - $80,000 - $50,000 = $650,000. General property taxes are general revenues, not program revenues.","Omits the capital grants, which are program revenues because they are restricted to the function.","Deducts only charges for services; program revenues include operating and capital grants.","Reports gross expenses with no program revenues offsetting them."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Net program cost = function expenses less charges for services and operating and capital grants; taxes are general revenues.","from":"2026-01-01","calc":1,"steps":["900,000 - 120,000 - 80,000 - 50,000 = 650,000"]}},{"i":"FAR-I-C-0018","t":"Neville City reports capital assets, net of accumulated depreciation, of $30,000,000. It issued $12,000,000 of bonds to acquire and construct those assets, of which $2,000,000 of proceeds has not yet been spent and is held in restricted cash. What is the city's net investment in capital assets?","mc":{"s":"Neville City reports capital assets, net of accumulated depreciation, of $30,000,000. It issued $12,000,000 of bonds to acquire and construct those assets, of which $2,000,000 of proceeds has not yet been spent and is held in restricted cash. What is the city's net investment in capital assets?","d":"","o":["$18,000,000","$20,000,000","$22,000,000","$30,000,000"],"a":2,"cite":"GASB 34","rat":"Debt attributable to unspent proceeds is excluded: $30,000,000 - ($12,000,000 - $2,000,000) = $20,000,000.","ex":["Deducts all of the bonds, including the portion tied to unspent proceeds that have not yet been used for capital assets.","Debt attributable to unspent proceeds is excluded: $30,000,000 - ($12,000,000 - $2,000,000) = $20,000,000.","Adds the unspent proceeds back a second time; unspent proceeds are not a capital asset.","Reports capital assets without deducting any related debt."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Net investment in capital assets = capital assets less related debt, excluding debt attributable to unspent proceeds.","from":"2026-01-01","calc":1,"steps":["Debt related to spent proceeds = 12000000 - 2000000 = 10000000","30000000 - 10000000 = 20000000"]}},{"i":"FAR-I-C-0019","t":"Besides management's discussion and analysis, which of the following is required supplementary information for a general-purpose government?","mc":{"s":"Besides management's discussion and analysis, which of the following is required supplementary information for a general-purpose government?","d":"","o":["A statement of net position for governmental activities and business-type activities","A statement of revenues, expenditures and changes in fund balance for major governmental funds","A budgetary comparison schedule for the general fund and each major special revenue fund with a legally adopted budget","Notes describing significant accounting policies and long-term debt"],"a":3,"cite":"GASB 34","rat":"Budgetary comparison schedules are RSI, presented with original budget, final budget and actual amounts.","ex":["This is a basic financial statement, not RSI.","This is a basic financial statement.","Budgetary comparison schedules are RSI, presented with original budget, final budget and actual amounts.","Notes are part of the basic financial statements."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"RSI includes MD&A, budgetary comparison schedules for the general fund and major special revenue funds, and certain pension and OPEB schedules.","from":"2026-01-01"}},{"i":"FAR-I-C-0020","t":"At the measurement date, the total pension liability of a cost-sharing plan's employer, Orchard County, was $90,000,000 and the plan's fiduciary net position attributable to the county was $62,000,000. What net pension liability does the county report in its government-wide statement of net position?","mc":{"s":"At the measurement date, the total pension liability of a cost-sharing plan's employer, Orchard County, was $90,000,000 and the plan's fiduciary net position attributable to the county was $62,000,000. What net pension liability does the county report in its government-wide statement of net position?","d":"","o":["$28,000,000","$62,000,000","$90,000,000","$152,000,000"],"a":1,"cite":"GASB 68","rat":"Net pension liability = total pension liability less fiduciary net position = $28,000,000.","ex":["Net pension liability = total pension liability less fiduciary net position = $28,000,000.","Reports the plan's assets only, not the shortfall.","Reports the total pension liability without offsetting plan assets.","Adds plan assets to the liability; they reduce the liability."],"wt":["","concept","concept","calc"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The net pension liability is the total pension liability minus the plan's fiduciary net position.","from":"2026-01-01","calc":1,"steps":["90,000,000 - 62,000,000 = 28,000,000"]}},{"i":"FAR-I-C-0021","t":"Weston County's fiscal year ends December 31, 2026. Its net pension liability was measured as of June 30, 2026, the plan's fiscal year-end. Between July 1 and December 31, 2026, the county contributed $2,000,000 to the plan. How is this reported in the county's government-wide statement of net position?","mc":{"s":"Weston County's fiscal year ends December 31, 2026. Its net pension liability was measured as of June 30, 2026, the plan's fiscal year-end. Between July 1 and December 31, 2026, the county contributed $2,000,000 to the plan. How is this reported in the county's government-wide statement of net position?","d":"","o":["As a reduction of the net pension liability of $2,000,000 at December 31, 2026, because the cash was paid to the plan","As pension expense of $2,000,000, because the contributions were paid during the reporting period","As a prepaid asset of $2,000,000 until the next measurement date, when it is recognized as expense","As a deferred outflow of resources of $2,000,000, because the contributions were made after the measurement date"],"a":4,"cite":"GASB Statement 68, paragraph 57","rat":"Contributions made after the measurement date are deferred outflows that reduce the net pension liability in the next measurement.","ex":["The liability is measured at the measurement date; later contributions are reported as deferred outflows.","Pension expense is determined by the plan's actuarial calculations, not cash contributions.","The standard specifies a deferred outflow, not a prepaid asset.","Contributions made after the measurement date are deferred outflows that reduce the net pension liability in the next measurement."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"C","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Employer contributions after the pension measurement date are reported as deferred outflows of resources at the reporting date.","from":"2026-01-01"}},{"i":"FAR-I-C-0022","t":"On January 1, 2026, Brookfield City, as lessee, began a 5-year noncancellable lease of equipment, paying $100,000 at the end of each year. The rate implicit in the lease is 6%. The equipment will be used in general fund operations. What amount should the general fund report as an other financing source at lease commencement? (PV of an ordinary annuity of $1 for 5 periods at 6% = 4.212364.)","mc":{"s":"On January 1, 2026, Brookfield City, as lessee, began a 5-year noncancellable lease of equipment, paying $100,000 at the end of each year. The rate implicit in the lease is 6%. The equipment will be used in general fund operations. What amount should the general fund report as an other financing source at lease commencement? (PV of an ordinary annuity of $1 for 5 periods at 6% = 4.212364.)","d":"","o":["$0","$100,000","$421,236","$500,000"],"a":3,"cite":"GASB 87","rat":"The present value of the lease payments is $100,000 x 4.212364 = $421,236, reported as capital outlay expenditure and an other financing source.","ex":["Reports nothing at commencement, which was the old treatment of operating leases.","Uses only the first year's payment, which ignores the remaining lease payments.","The present value of the lease payments is $100,000 x 4.212364 = $421,236, reported as capital outlay expenditure and an other financing source.","Uses the total of undiscounted payments; the lease liability is measured at present value."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A lessee recognizes a lease liability and right-to-use asset at present value; governmental funds report an expenditure and other financing source.","from":"2026-01-01","calc":1,"steps":["PV = 100,000 x 4.212364 = 421,236","General fund: capital outlay expenditure 421,236 and other financing source 421,236"]}},{"i":"FAR-I-C-0023","t":"On January 1, 2026, Brookfield City began a 5-year lease of equipment, paying $100,000 at the end of each year, discounted at 6% (present value $421,236 at commencement). The equipment is used in governmental activities. What is the lease liability in the government-wide statement of net position at December 31, 2026, after the first payment? (Round to the nearest dollar.)","mc":{"s":"On January 1, 2026, Brookfield City began a 5-year lease of equipment, paying $100,000 at the end of each year, discounted at 6% (present value $421,236 at commencement). The equipment is used in governmental activities. What is the lease liability in the government-wide statement of net position at December 31, 2026, after the first payment? (Round to the nearest dollar.)","d":"","o":["$321,236","$346,510","$400,000","$421,236"],"a":2,"cite":"GASB 87","rat":"Interest of $25,274 accrues, so the liability is $421,236 + $25,274 - $100,000 = $346,510.","ex":["Subtracts the payment without accruing interest; part of the payment is interest and does not reduce principal by the full amount.","Interest of $25,274 accrues, so the liability is $421,236 + $25,274 - $100,000 = $346,510.","Starts from the undiscounted total payments instead of the present value.","Leaves the liability unchanged at the commencement amount, ignoring the payment and interest."],"wt":["calc","","concept","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"The lease liability accretes interest at the discount rate and is reduced by lease payments.","from":"2026-01-01","calc":1,"steps":["Interest = 421,236 x 6% = 25,274","Liability = 421,236 + 25,274 - 100,000 = 346,510"]}},{"i":"FAR-I-C-0024","t":"Which of the following activities must be reported in an enterprise fund?","mc":{"s":"Which of the following activities must be reported in an enterprise fund?","d":"","o":["A fire department financed mainly by property taxes, with only small fees for inspections","A public library funded from taxes and small overdue fines, which cover a modest part of its costs","A municipal parking garage financed by revenue bonds whose only pledged source of repayment is parking fees","A road maintenance program funded by a state motor fuel tax restricted to road expenditures"],"a":3,"cite":"GASB 34","rat":"Activities financed with debt backed solely by fees and charges must be reported as enterprise funds.","ex":["A tax-supported service does not meet an enterprise fund criterion.","Fees are minor and the library depends on taxes.","Activities financed with debt backed solely by fees and charges must be reported as enterprise funds.","A restricted tax revenue would generally be a special revenue fund."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Use an enterprise fund when debt is backed solely by fees, law requires cost recovery through fees, or policy sets fees to recover costs.","from":"2026-01-01"}},{"i":"FAR-I-C-0025","t":"A city's water enterprise fund received a $200,000 operating subsidy from the general fund, paid $80,000 of interest on revenue bonds that financed its treatment plant, and received $15,000 of interest on investments. How should these be classified in the statement of cash flows?","mc":{"s":"A city's water enterprise fund received a $200,000 operating subsidy from the general fund, paid $80,000 of interest on revenue bonds that financed its treatment plant, and received $15,000 of interest on investments. How should these be classified in the statement of cash flows?","d":"","o":["Subsidy: noncapital financing; interest paid: capital and related financing; interest received: investing","Subsidy: operating; interest paid: operating; interest received: operating","Subsidy: capital and related financing; interest paid: noncapital financing; interest received: investing","Subsidy: noncapital financing; interest paid: noncapital financing; interest received: operating"],"a":1,"cite":"GASB 9","rat":"Proprietary funds use four categories, and each of these items belongs to a different one.","ex":["Proprietary funds use four categories, and each of these items belongs to a different one.","Interest and subsidies are classified differently under the four-category format.","The subsidy funds operations, and the interest is on capital debt; the categories are reversed.","Interest on debt issued to finance capital assets is capital and related financing; interest on investments is investing."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Proprietary funds report operating, noncapital financing, capital and related financing, and investing activities.","from":"2026-01-01"}},{"i":"FAR-I-C-0026","t":"Camden County's treasurer collects property taxes for three school districts and distributes them to the districts monthly. The county holds no beneficial interest in the collections. How should the county report this activity?","mc":{"s":"Camden County's treasurer collects property taxes for three school districts and distributes them to the districts monthly. The county holds no beneficial interest in the collections. How should the county report this activity?","d":"","o":["In the general fund, because the county's treasurer collects and disburses the money","In an enterprise fund, because the county provides a collection service to other governments","In a special revenue fund, because the collections are restricted for distribution to the districts","In a custodial fund, a fiduciary fund type, with economic resources measurement focus"],"a":4,"cite":"GASB 84","rat":"Assets held for others and not under a trust arrangement are reported in custodial funds.","ex":["The resources belong to the school districts, not the county's general fund.","The county does not charge for a business-type service; it merely holds assets for others.","A special revenue fund reports the government's own resources, not resources it holds for others.","Assets held for others and not under a trust arrangement are reported in custodial funds."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Assets a government holds for others outside a trust are reported in custodial funds, a fiduciary fund type.","from":"2026-01-01"}},{"i":"FAR-I-C-0027","t":"The general fund of Jasper Village holds debt investments that cost $500,000. Their fair value was $505,000 at the beginning of 2026 and $512,000 at the end. The fund received interest of $20,000 in 2026 and sold no investments. What investment income should the fund report for 2026?","mc":{"s":"The general fund of Jasper Village holds debt investments that cost $500,000. Their fair value was $505,000 at the beginning of 2026 and $512,000 at the end. The fund received interest of $20,000 in 2026 and sold no investments. What investment income should the fund report for 2026?","d":"","o":["$12,000","$20,000","$27,000","$32,000"],"a":3,"cite":"GASB Statement 31, paragraphs 13-14","rat":"Investment income includes interest and the net change in fair value: $20,000 + ($512,000 - $505,000) = $27,000.","ex":["Reports total unrealized gain since purchase without interest.","Reports interest only; the change in fair value is also investment income.","Investment income includes interest and the net change in fair value: $20,000 + ($512,000 - $505,000) = $27,000.","Includes the whole gain over cost, part of which ($5,000) was recognized in the prior year."],"wt":["concept","concept","","calc"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Investments are reported at fair value, and the change in fair value is recognized as investment income for the period.","from":"2026-01-01","calc":1,"steps":["Change in fair value = 512000 - 505000 = 7000","Investment income = 20000 + 7000 = 27000"]}},{"i":"FAR-I-C-0028","t":"Which of the following is required if a city elects the modified approach for its eligible road network?","mc":{"s":"Which of the following is required if a city elects the modified approach for its eligible road network?","d":"","o":["The city records depreciation on the network but reports the expenditures to maintain it as capital assets","The city reports the network at fair value each year, with changes in fair value in the statement of activities","The city excludes the road network from the statement of net position because it is not depreciated","The city does not record depreciation on the network, provided it maintains the roads at or above a condition level it has set and documents it"],"a":4,"cite":"GASB 34","rat":"Under the modified approach, depreciation is not recorded as long as the asset is preserved at the established level.","ex":["Under the modified approach depreciation is not recorded; maintenance is expensed.","The modified approach does not use fair value; the asset stays at cost.","The network is still reported as a capital asset.","Under the modified approach, depreciation is not recorded as long as the asset is preserved at the established level."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"The modified approach skips depreciation on eligible infrastructure that is maintained at an established condition level, with expenses for maintenance.","from":"2026-01-01"}},{"i":"FAR-I-C-0029","t":"A state awarded Elk River City a $900,000 grant to reimburse allowable costs of a street project. As of December 31, 2026 the city had incurred $350,000 of allowable costs and had received $200,000 in cash. The state pays reimbursements within 30 days of billing, and the city billed the full $350,000 in December. What grant revenue does the capital projects fund report for 2026?","mc":{"s":"A state awarded Elk River City a $900,000 grant to reimburse allowable costs of a street project. As of December 31, 2026 the city had incurred $350,000 of allowable costs and had received $200,000 in cash. The state pays reimbursements within 30 days of billing, and the city billed the full $350,000 in December. What grant revenue does the capital projects fund report for 2026?","d":"","o":["$200,000","$350,000","$550,000","$900,000"],"a":2,"cite":"GASB 33","rat":"Revenue is recognized as eligibility requirements are met by incurring allowable costs, and the billed amount is available: $350,000.","ex":["Recognizes only the cash received; the receivable for the reimbursement billed and collected within 30 days also qualifies.","Revenue is recognized as eligibility requirements are met by incurring allowable costs, and the billed amount is available: $350,000.","Adds cash received to costs incurred, double counting the reimbursement.","Recognizes the entire grant award although the city has not yet met the eligibility requirement for the remainder."],"wt":["concept","","calc","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Reimbursement grants are recognized as revenue when the eligibility requirement (incurring allowable costs) is met and the amount is available.","from":"2026-01-01","calc":1,"steps":["Eligibility met for costs incurred: 350,000","Available: billed in December, paid within 30 days","Revenue = 350,000"]}},{"i":"FAR-I-C-0030","t":"Dover City has $2,000,000 of general obligation bonds carrying a 6% stated rate, with interest payable each March 1 and September 1. The city uses a debt service fund and reports government-wide statements. What amount of accrued interest payable is reported at December 31 in the government-wide statement of net position but NOT in the debt service fund?","mc":{"s":"Dover City has $2,000,000 of general obligation bonds carrying a 6% stated rate, with interest payable each March 1 and September 1. The city uses a debt service fund and reports government-wide statements. What amount of accrued interest payable is reported at December 31 in the government-wide statement of net position but NOT in the debt service fund?","d":"","o":["$40,000","$60,000","$80,000","$120,000"],"a":1,"cite":"GASB Interpretation 6; GASB 34","rat":"Interest accrues for September through December: $2,000,000 x 6% x 4/12 = $40,000.","ex":["Interest accrues for September through December: $2,000,000 x 6% x 4/12 = $40,000. The debt service fund records interest when due.","Uses six months of interest, the amount for a semiannual period rather than the four months elapsed since September 1.","Uses eight months of interest, which is the period since the last March 1 payment date.","Uses a full year of interest, ignoring the payments already made."],"wt":["","calc","calc","calc"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Governmental funds record interest expenditure when due; the government-wide statements accrue interest from the last payment date.","from":"2026-01-01","calc":1,"steps":["Accrual period September 1 to December 31 = 4 months","2,000,000 x 6% x 4/12 = 40,000"]}}],"4":[{"i":"FAR-I-D-0001","t":"Falcon Industries reported net income of $1,200,000 for 2026. It has cumulative preferred stock with annual dividends of $100,000 (not declared in 2026). Common shares outstanding were 500,000 on January 1; the company issued 120,000 shares on April 1 and bought back 30,000 shares as treasury stock on October 1. What is basic earnings per share for 2026?","mc":{"s":"Falcon Industries reported net income of $1,200,000 for 2026. It has cumulative preferred stock with annual dividends of $100,000 (not declared in 2026). Common shares outstanding were 500,000 on January 1; the company issued 120,000 shares on April 1 and bought back 30,000 shares as treasury stock on October 1. What is basic earnings per share for 2026?","d":"","o":["$1.86","$1.89","$2.06","$2.40"],"a":2,"cite":"ASC 260","rat":"Weighted shares = 500,000 + 120,000 x 9/12 - 30,000 x 3/12 = 582,500; ($1,200,000 - $100,000) / 582,500 = $1.89.","ex":["Uses year-end shares of 590,000 instead of the weighted average, which ignores the timing of the issue and buyback.","Weighted shares = 500,000 + 120,000 x 9/12 - 30,000 x 3/12 = 582,500; ($1,200,000 - $100,000) / 582,500 = $1.89.","Does not deduct the cumulative preferred dividends, which reduce income available to common shareholders whether or not declared.","Uses only the shares outstanding at the beginning of the year and no preferred dividend adjustment."],"wt":["calc","","concept","calc"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Basic EPS = (net income - preferred dividends) / weighted-average common shares; cumulative preferred dividends are deducted even if undeclared.","from":"2026-01-01","calc":1,"steps":["Weighted shares = 500000 + 90000 - 7500 = 582500","Numerator = 1200000 - 100000 = 1100000","EPS = 1.8884"]}},{"i":"FAR-I-D-0002","t":"Granite Corp. earned $960,000 in 2026 and had no preferred stock. It had 400,000 common shares outstanding on January 1, issued 60,000 shares on July 1, and declared a 2-for-1 stock split in February 2027, before its 2026 financial statements were issued. What basic earnings per share should Granite report for 2026?","mc":{"s":"Granite Corp. earned $960,000 in 2026 and had no preferred stock. It had 400,000 common shares outstanding on January 1, issued 60,000 shares on July 1, and declared a 2-for-1 stock split in February 2027, before its 2026 financial statements were issued. What basic earnings per share should Granite report for 2026?","d":"","o":["$1.12","$1.20","$2.23","$2.40"],"a":1,"cite":"ASC 260","rat":"Weighted shares before the split = 400,000 + 60,000 x 6/12 = 430,000; after retroactive restatement = 860,000; EPS = $1.12.","ex":["Weighted shares before the split = 400,000 + 60,000 x 6/12 = 430,000; after retroactive restatement = 860,000; EPS = $1.12.","Restates for the split but ignores the July 1 issuance of shares in the weighted average.","Weights the July 1 issuance but does not restate for the split, which must be applied retroactively.","Uses only the opening shares and ignores both the issuance and the split."],"wt":["","calc","concept","concept"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Stock splits and stock dividends are applied retroactively to all periods presented, even if they occur after year-end and before issuance.","from":"2026-01-01","calc":1,"steps":["Weighted shares = 400000 + 60000x6/12 = 430000","After 2-for-1 split = 860000","EPS = 1.1163"]}},{"i":"FAR-I-D-0003","t":"Mesa Corp. reported net income of $800,000 and had 400,000 weighted-average common shares for 2026. Throughout the year it had $1,000,000 of 5% convertible bonds (issued at par) outstanding, convertible into 20,000 common shares. The tax rate is 25%. What is diluted EPS for 2026?","mc":{"s":"Mesa Corp. reported net income of $800,000 and had 400,000 weighted-average common shares for 2026. Throughout the year it had $1,000,000 of 5% convertible bonds (issued at par) outstanding, convertible into 20,000 common shares. The tax rate is 25%. What is diluted EPS for 2026?","d":"","o":["$1.90","$1.99","$2.00","$2.02"],"a":2,"cite":"ASC 260","rat":"If-converted method: add back after-tax interest ($37,500) and add 20,000 shares: $837,500 / 420,000 = $1.99.","ex":["Adds the shares but does not add back the after-tax interest saved on conversion.","If-converted method: add back after-tax interest ($37,500) and add 20,000 shares: $837,500 / 420,000 = $1.99.","Reports basic EPS of $2.00; the convertible bonds are dilutive and must be included.","Adds back interest before tax, which overstates the numerator; the add-back is net of tax."],"wt":["concept","","concept","calc"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"If-converted method: add after-tax interest back to the numerator and add the conversion shares to the denominator if dilutive.","from":"2026-01-01","calc":1,"steps":["After-tax interest = 1000000x5%x(1-0.25) = 37500","Numerator = 837500; denominator = 420000","Diluted EPS = 1.9940"]}},{"i":"FAR-I-D-0004","t":"Zephyr Inc. reported net income of $1,000,000 and had 500,000 weighted-average common shares. Throughout 2026 there were 60,000 outstanding stock options with an exercise price of $30. The average market price of the common stock during 2026 was $40 and the year-end price was $50. What is diluted EPS?","mc":{"s":"Zephyr Inc. reported net income of $1,000,000 and had 500,000 weighted-average common shares. Throughout 2026 there were 60,000 outstanding stock options with an exercise price of $30. The average market price of the common stock during 2026 was $40 and the year-end price was $50. What is diluted EPS?","d":"","o":["$1.79","$1.91","$1.94","$2.00"],"a":3,"cite":"ASC 260","rat":"Incremental shares = 60,000 - (60,000 x $30 / $40) = 15,000; $1,000,000 / 515,000 = $1.94.","ex":["Adds all the option shares without assuming the proceeds are used to repurchase shares.","Uses the year-end price instead of the average market price for the assumed buyback.","Incremental shares = 60,000 - (60,000 x $30 / $40) = 15,000; $1,000,000 / 515,000 = $1.94.","Ignores the options, which are dilutive because the average price exceeds the exercise price."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Treasury stock method: assumed exercise proceeds buy back shares at the average market price; only the net incremental shares are added.","from":"2026-01-01","calc":1,"steps":["Assumed repurchase = 60000x30/40 = 45000","Incremental = 60000 - 45000 = 15000","Diluted EPS = 1000000/515000 = 1.9417"]}},{"i":"FAR-I-D-0005","t":"Torrey Co. reported net income of $700,000 with 350,000 weighted-average common shares for 2026. Two option grants were outstanding all year: 50,000 options with an exercise price of $25 and 40,000 options with an exercise price of $45. The average market price was $35. What is diluted EPS?","mc":{"s":"Torrey Co. reported net income of $700,000 with 350,000 weighted-average common shares for 2026. Two option grants were outstanding all year: 50,000 options with an exercise price of $25 and 40,000 options with an exercise price of $45. The average market price was $35. What is diluted EPS?","d":"","o":["$1.59","$1.92","$1.98","$2.00"],"a":2,"cite":"ASC 260","rat":"Only the $25 options are dilutive: incremental shares 14,286; $700,000 / 364,286 = $1.92.","ex":["Adds all option shares without applying the treasury stock method.","Only the $25 options are dilutive: incremental shares 14,286; $700,000 / 364,286 = $1.92. The $45 options are excluded as antidilutive.","Includes the $45 options, whose exercise price exceeds the average price and would increase EPS.","Reports basic EPS; the $25 options are dilutive."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Options with an exercise price above the average market price are antidilutive and excluded from diluted EPS.","from":"2026-01-01","calc":1,"steps":["Dilutive tranche incremental shares = 50000 - 35714 = 14286","Diluted EPS = 700000/364286 = 1.9216"]}},{"i":"FAR-I-D-0006","t":"Ulster Corp. reported net income of $600,000 in 2026 and had 300,000 common shares outstanding all year. It also has noncumulative preferred stock with an annual dividend of $80,000; the board declared no dividends on the preferred stock in 2026. What is basic EPS?","mc":{"s":"Ulster Corp. reported net income of $600,000 in 2026 and had 300,000 common shares outstanding all year. It also has noncumulative preferred stock with an annual dividend of $80,000; the board declared no dividends on the preferred stock in 2026. What is basic EPS?","d":"","o":["$1.73","$1.87","$2.00","$2.27"],"a":3,"cite":"ASC 260","rat":"Undeclared noncumulative dividends are not deducted: $600,000 / 300,000 = $2.00.","ex":["Deducts the undeclared noncumulative dividend; it is deducted only if declared.","Deducts half of the dividend, which has no basis.","Undeclared noncumulative dividends are not deducted: $600,000 / 300,000 = $2.00.","Adds the preferred dividend to income, reversing the adjustment."],"wt":["concept","calc","","calc"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Only declared dividends on noncumulative preferred stock, and all dividends on cumulative preferred stock, reduce income available to common.","from":"2026-01-01","calc":1,"steps":["No dividend declared: EPS = 600000/300000 = 2.00"]}},{"i":"FAR-I-D-0007","t":"Norwood Corp. has several potentially dilutive securities outstanding: convertible bonds, convertible preferred stock and stock options. In which order does it include them in the computation of diluted EPS?","mc":{"s":"Norwood Corp. has several potentially dilutive securities outstanding: convertible bonds, convertible preferred stock and stock options. In which order does it include them in the computation of diluted EPS?","d":"","o":["In the order in which the securities were issued, beginning with the oldest, without regard to the effect on EPS","From the least dilutive to the most dilutive, so basic EPS is reduced by the smallest effect first","From the most dilutive to the least dilutive, based on incremental EPS, stopping when EPS would increase","All at once, with every security included whether it is dilutive or antidilutive, to give the maximum dilution"],"a":3,"cite":"ASC 260","rat":"Securities are ranked by earnings effect per incremental share, and any that would raise EPS are excluded.","ex":["Ranking is by dilutive effect, not by date of issue.","Reverse order would not produce the lowest EPS figure.","Securities are ranked by earnings effect per incremental share, and any that would raise EPS are excluded.","Antidilutive securities are excluded from diluted EPS."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"D","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Diluted EPS ranks potentially dilutive securities from most to least dilutive and excludes those that are antidilutive.","from":"2026-01-01"}},{"i":"FAR-I-D-0008","t":"Oakmont Corp. reported income from continuing operations of $1,000,000 and a loss from discontinued operations, net of tax, of $200,000. Preferred dividends declared were $100,000. Weighted-average common shares were 400,000. What is basic EPS from continuing operations?","mc":{"s":"Oakmont Corp. reported income from continuing operations of $1,000,000 and a loss from discontinued operations, net of tax, of $200,000. Preferred dividends declared were $100,000. Weighted-average common shares were 400,000. What is basic EPS from continuing operations?","d":"","o":["$1.75","$2.00","$2.25","$2.50"],"a":3,"cite":"ASC 260","rat":"Income from continuing operations less preferred dividends, divided by shares: ($1,000,000 - $100,000) / 400,000 = $2.25.","ex":["Subtracts the discontinued operations loss, which is excluded from continuing operations EPS.","Subtracts the loss but no preferred dividends, mixing both errors.","Income from continuing operations less preferred dividends, divided by shares: ($1,000,000 - $100,000) / 400,000 = $2.25.","Does not deduct preferred dividends, which are subtracted from each income figure used for EPS."],"wt":["concept","calc","","calc"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"EPS from continuing operations uses income from continuing operations less preferred dividends; discontinued operations are separate.","from":"2026-01-01","calc":1,"steps":["(1000000 - 100000) / 400000 = 2.25"]}},{"i":"FAR-I-D-0009","t":"Delmar Corp. has six operating segments. Total revenues of all segments are $100 million, combined profit of the profitable segments is $13.7 million, combined loss of the loss-making segment is $2.6 million, and total assets are $120 million. Using only the 10% quantitative tests, how many segments are reportable?","mc":{"s":"Delmar Corp. has six operating segments. Total revenues of all segments are $100 million, combined profit of the profitable segments is $13.7 million, combined loss of the loss-making segment is $2.6 million, and total assets are $120 million. Using only the 10% quantitative tests, how many segments are reportable?","d":"","o":["3","4","5","6"],"a":3,"cite":"ASC 280","rat":"A, B and C meet the revenue or asset test; D meets the profit test ($1.5M is 10% of $13.7M or more); E meets the loss test ($2.6M).","ex":["Counts only the segments that meet the revenue test, ignoring the profit or loss and asset tests.","Excludes segment E because it has a loss, but the loss test uses the absolute value.","A, B and C meet the revenue or asset test; D meets the profit test ($1.5M is 10% of $13.7M or more); E meets the loss test ($2.6M). F meets none. Total: 5 reportable segments.","Includes all six segments, including F, which meets none of the tests."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"An operating segment is reportable if revenue, the greater of combined profit or combined loss, or assets is at least 10% of the total.","tb":[["Segment","Revenue ($M)","Profit (loss) ($M)","Assets ($M)"],["A","45.0","8.0","60"],["B","25.0","3.0","30"],["C","12.0","1.0","15"],["D","9.0","1.5","8"],["E","6.0","(2.6)","5"],["F","3.0","0.2","2"]],"from":"2026-01-01","calc":1,"steps":["Revenue threshold $10M: A, B, C","Profit test: greater of profits $13.7M or loss $2.6M = $13.7M; threshold $1.37M: A, B, D, E (absolute loss $2.6M)","Assets threshold $12M: A, B, C","Reportable: A, B, C, D, E = 5"]}},{"i":"FAR-I-D-0010","t":"After applying the 10% tests, the reportable segments of Ferris Inc. account for only 68% of consolidated external revenue. What must Ferris do?","mc":{"s":"After applying the 10% tests, the reportable segments of Ferris Inc. account for only 68% of consolidated external revenue. What must Ferris do?","d":"","o":["Report additional operating segments, even if below the 10% thresholds, until at least 75% of consolidated revenue is included","Combine all remaining segments into one 'all other' category, since the 10% tests were applied correctly","Reduce the reportable segments to the largest one, because 68% is above the 50% minimum threshold","Disclose the shortfall in the notes and continue with the segments already identified as reportable"],"a":1,"cite":"ASC 280","rat":"If the reportable segments' external revenue is under 75% of consolidated revenue, additional segments are added until 75% is reached.","ex":["If the reportable segments' external revenue is under 75% of consolidated revenue, additional segments are added until 75% is reached.","'All other' is allowed only after the 75% threshold is met.","There is no 50% rule; the 75% threshold is the test.","Disclosure does not replace the requirement to add segments."],"wt":["","concept","limit","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Reportable segments must cover at least 75% of consolidated external revenue; add segments until they do.","from":"2026-01-01"}},{"i":"FAR-I-D-0011","t":"Vantage Holdings is a public company with a single reportable segment. Which disclosure about that segment is required?","mc":{"s":"Vantage Holdings is a public company with a single reportable segment. Which disclosure about that segment is required?","d":"","o":["None, since segment disclosures apply only to entities with two or more reportable segments","Only revenue and total assets for the segment, since profit is disclosed on the income statement","Significant segment expenses regularly provided to the chief operating decision maker, along with the title and position of that person","Segment expenses only if they exceed 10% of consolidated expenses, together with the segment's asset totals"],"a":3,"cite":"ASU 2023-07; ASC 280","rat":"Segment disclosures apply to entities with one reportable segment and include significant segment expenses and the CODM's title and position.","ex":["Single-segment entities must provide all segment disclosures.","Required disclosures include the measure of profit or loss and significant expenses.","Segment disclosures apply to entities with one reportable segment and include significant segment expenses and the CODM's title and position.","There is no 10% expense threshold; significant expenses are those regularly provided to the CODM."],"wt":["concept","concept","","limit"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Public entities disclose significant segment expenses provided to the CODM and the CODM's title, including entities with one reportable segment.","from":"2026-01-01"}},{"i":"FAR-I-D-0012","t":"The reportable segments of Cormorant Corp. have combined profit of $13,700,000. Cormorant also has $2,900,000 of unallocated corporate expenses and $400,000 of intersegment profit that is eliminated in consolidation. What is consolidated income before income taxes?","mc":{"s":"The reportable segments of Cormorant Corp. have combined profit of $13,700,000. Cormorant also has $2,900,000 of unallocated corporate expenses and $400,000 of intersegment profit that is eliminated in consolidation. What is consolidated income before income taxes?","d":"","o":["$10,400,000","$10,800,000","$11,200,000","$13,700,000"],"a":1,"cite":"ASC 280","rat":"$13,700,000 - $2,900,000 - $400,000 = $10,400,000.","ex":["$13,700,000 - $2,900,000 - $400,000 = $10,400,000.","Omits the elimination of intersegment profit.","Adds the intersegment profit instead of eliminating it.","Reports segment profit with no reconciling items."],"wt":["","concept","calc","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Reconcile total reportable segment profit to consolidated income before taxes for unallocated amounts and eliminations.","from":"2026-01-01","calc":1,"steps":["13700000 - 2900000 - 400000 = 10400000"]}},{"i":"FAR-I-D-0013","t":"The chief operating decision maker of Hadley Inc. reviews segment profit measured on a basis that differs from GAAP: it excludes stock-based compensation and uses management's allocation of shared costs. What is required in the segment note?","mc":{"s":"The chief operating decision maker of Hadley Inc. reviews segment profit measured on a basis that differs from GAAP: it excludes stock-based compensation and uses management's allocation of shared costs. What is required in the segment note?","d":"","o":["Restate each segment's profit under GAAP and drop the internal measure from the financial statements entirely","Report only the GAAP measure that appears in the consolidated statements and disclose nothing about the internal measure","Report the internal measure without reconciliation, because non-GAAP segment measures are exempt from reconciliation","Report the measure the CODM uses, explain how it is measured, and reconcile total segment profit to consolidated income before taxes"],"a":4,"cite":"ASC 280","rat":"Segment reporting follows the management approach, with reconciliations to consolidated GAAP amounts.","ex":["The measure used by the CODM is reported, not a restated GAAP measure.","The internal measure the CODM uses is the required disclosure.","A reconciliation to consolidated income before taxes is required.","Segment reporting follows the management approach, with reconciliations to consolidated GAAP amounts."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Segment reporting uses the management approach: report the CODM's measure, explain it and reconcile to consolidated amounts.","from":"2026-01-01"}},{"i":"FAR-I-D-0014","t":"Peregrine Inc. had consolidated revenues of $180 million. Sales to Customer X were $22 million and sales to Customer Y were $17 million. Zeta Ltd. and Willow Corp., two companies under common control of the same parent, bought $9 million and $10 million, respectively. How many customers (counting entities under common control as one) must Peregrine disclose as major customers?","mc":{"s":"Peregrine Inc. had consolidated revenues of $180 million. Sales to Customer X were $22 million and sales to Customer Y were $17 million. Zeta Ltd. and Willow Corp., two companies under common control of the same parent, bought $9 million and $10 million, respectively. How many customers (counting entities under common control as one) must Peregrine disclose as major customers?","d":"","o":["1","2","3","4"],"a":2,"cite":"ASC 280","rat":"The threshold is 10% of consolidated revenue, $18 million.","ex":["Counts only Customer X and treats Zeta and Willow separately, ignoring that entities under common control are one customer.","The threshold is 10% of consolidated revenue, $18 million. Customer X ($22M) and the common-control group ($19M) exceed it; Y ($17M) does not.","Counts Customer Y as well, which is below the $18 million threshold.","Counts every named customer, including Y and the two common-control companies separately."],"wt":["concept","","limit","concept"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Disclose any single customer (with entities under common control as one) providing 10% or more of consolidated revenue.","from":"2026-01-01","calc":1,"steps":["Threshold = 10% x 180 = 18M","X = 22M (yes); Y = 17M (no); Zeta + Willow = 19M (yes)","Count = 2"]}},{"i":"FAR-I-D-0015","t":"Kestrel Inc. paid its $240,000 annual property tax bill in January 2026. What amount of property tax expense should it report in its first-quarter interim statements?","mc":{"s":"Kestrel Inc. paid its $240,000 annual property tax bill in January 2026. What amount of property tax expense should it report in its first-quarter interim statements?","d":"","o":["$0","$60,000","$120,000","$240,000"],"a":2,"cite":"ASC 270","rat":"A cost benefiting the whole year is allocated across the interim periods: $240,000 / 4 = $60,000.","ex":["Defers all expense until year-end, when the cost benefits each quarter.","A cost benefiting the whole year is allocated across the interim periods: $240,000 / 4 = $60,000.","Charges two quarters' worth, which has no basis.","Charges the whole year to the quarter in which it was paid."],"wt":["concept","","calc","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Costs that benefit several interim periods are allocated to those periods rather than expensed when paid.","from":"2026-01-01","calc":1,"steps":["240,000 / 4 quarters = 60,000"]}},{"i":"FAR-I-D-0016","t":"Lumen Corp. recorded first-quarter tax expense of $120,000 on ordinary income of $400,000 using an estimated annual effective tax rate of 30%. In the second quarter, year-to-date ordinary income was $900,000 and the estimated annual effective rate was revised to 28%. What income tax expense is reported for the second quarter?","mc":{"s":"Lumen Corp. recorded first-quarter tax expense of $120,000 on ordinary income of $400,000 using an estimated annual effective tax rate of 30%. In the second quarter, year-to-date ordinary income was $900,000 and the estimated annual effective rate was revised to 28%. What income tax expense is reported for the second quarter?","d":"","o":["$132,000","$140,000","$150,000","$252,000"],"a":1,"cite":"ASC 740","rat":"Year-to-date tax at 28% is $252,000, less the $120,000 already recorded, gives $132,000.","ex":["Year-to-date tax at 28% is $252,000, less the $120,000 already recorded, gives $132,000.","Applies the revised rate only to second-quarter income, missing the cumulative catch-up for the first quarter.","Applies the old 30% rate to second-quarter income, ignoring the revised annual rate.","Reports the year-to-date tax without subtracting the tax already recorded in the first quarter."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Interim tax expense = year-to-date ordinary income times the current estimated annual effective rate, less tax already recorded.","from":"2026-01-01","calc":1,"steps":["YTD tax = 900,000 x 28% = 252,000","Less first quarter 120,000 = 132,000"]}},{"i":"FAR-I-D-0017","t":"Which method should a company use to compute income tax expense for its first interim period?","mc":{"s":"Which method should a company use to compute income tax expense for its first interim period?","d":"","o":["Apply the estimated annual effective tax rate for the full year to first-quarter ordinary income","Apply the statutory rate to first-quarter income as though the quarter were a separate reporting year","Record no tax expense until the fourth quarter, when the annual tax return is filed","Use last year's actual effective tax rate regardless of any new estimates for the current year"],"a":1,"cite":"ASC 740","rat":"Interim periods are treated as part of the annual period, so tax uses the estimated annual effective rate.","ex":["Interim periods are treated as part of the annual period, so tax uses the estimated annual effective rate.","The discrete approach is not used for ordinary income.","Tax expense is recognized each interim period.","The current year's estimate must be used."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Interim tax uses the best estimate of the annual effective tax rate applied to year-to-date ordinary income.","from":"2026-01-01"}},{"i":"FAR-I-D-0018","t":"In the third quarter of 2026, a flood caused a casualty loss of $80,000 at Cove Manufacturing. How much of the loss should be reported in the third-quarter interim statements?","mc":{"s":"In the third quarter of 2026, a flood caused a casualty loss of $80,000 at Cove Manufacturing. How much of the loss should be reported in the third-quarter interim statements?","d":"","o":["$20,000","$40,000","$60,000","$80,000"],"a":4,"cite":"ASC 270","rat":"The full $80,000 is recognized in the interim period in which the unusual item occurs, not spread over the year.","ex":["Spreads the loss over four quarters, but unusual items are not allocated.","Spreads the loss over two quarters, which has no basis.","Spreads the loss over three quarters, which is not permitted for unusual items.","The full $80,000 is recognized in the interim period in which the unusual item occurs, not spread over the year."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"D","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Unusual or infrequent items are recognized in the interim period when they occur and are not allocated across the year.","from":"2026-01-01","calc":1,"steps":["Loss reported entirely in the third quarter: 80,000"]}},{"i":"FAR-I-D-0019","t":"Snowline Sports earns most of its revenue in the fourth quarter. How should it report revenue in its interim financial statements?","mc":{"s":"Snowline Sports earns most of its revenue in the fourth quarter. How should it report revenue in its interim financial statements?","d":"","o":["Spread expected annual revenue evenly across the four quarters to avoid volatility in interim results","Defer all revenue to the fourth quarter, when most sales are complete","Recognize revenue in the interim period it is earned, and disclose the seasonal nature of the business","Report revenue only annually and omit it from interim statements"],"a":3,"cite":"ASC 270","rat":"Interim revenue follows the same recognition principles as annual revenue; seasonality is disclosed and not smoothed.","ex":["Revenue is not smoothed across periods.","Revenue is recognized when earned, not deferred to the quarter with the most sales.","Interim revenue follows the same recognition principles as annual revenue; seasonality is disclosed and not smoothed.","Interim statements include revenue."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Interim revenue is recognized when earned, with seasonality disclosed, not smoothed.","from":"2026-01-01"}},{"i":"FAR-I-D-0020","t":"Marlin Corp. uses LIFO. In the first quarter, sales reduced inventory into an old LIFO layer with a cost of $12 per unit for 10,000 units. Marlin expects to replace those units by year-end at a current cost of $20 per unit. What cost of goods sold should Marlin report in the first quarter for these 10,000 units?","mc":{"s":"Marlin Corp. uses LIFO. In the first quarter, sales reduced inventory into an old LIFO layer with a cost of $12 per unit for 10,000 units. Marlin expects to replace those units by year-end at a current cost of $20 per unit. What cost of goods sold should Marlin report in the first quarter for these 10,000 units?","d":"","o":["$80,000","$120,000","$200,000","$320,000"],"a":3,"cite":"ASC 270-10-45-6","rat":"When a liquidation is expected to be replaced within the year, cost of goods sold uses replacement cost: 10,000 x $20 = $200,000.","ex":["Reports only the difference between replacement and historical cost.","Uses the old LIFO layer cost, which would inflate first-quarter income from a liquidation that will be reversed.","When a liquidation is expected to be replaced within the year, cost of goods sold uses replacement cost: 10,000 x $20 = $200,000.","Adds both costs together, which double counts the units."],"wt":["concept","concept","","calc"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A temporary LIFO liquidation expected to be replaced by year-end is costed at replacement cost in the interim statements.","from":"2026-01-01","calc":1,"steps":["10,000 units x $20 replacement cost = 200,000"]}},{"i":"FAR-I-D-0021","t":"Emerald Corp. is a large accelerated filer with a December 31 fiscal year-end. How many days after year-end is its annual Form 10-K due?","mc":{"s":"Emerald Corp. is a large accelerated filer with a December 31 fiscal year-end. How many days after year-end is its annual Form 10-K due?","d":"","o":["45 days","60 days","75 days","90 days"],"a":2,"cite":"Form 10-K","rat":"Large accelerated filers must file the 10-K within 60 days after fiscal year-end.","ex":["45 days is the 10-Q deadline for non-accelerated filers, not the 10-K deadline.","Large accelerated filers must file the 10-K within 60 days after fiscal year-end.","75 days applies to accelerated filers that are not large accelerated filers.","90 days applies to non-accelerated filers."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Form 10-K is due 60 days after year-end for large accelerated filers, 75 for accelerated filers and 90 for others.","from":"2026-01-01","calc":1,"steps":["Large accelerated filer: 60 days"]}},{"i":"FAR-I-D-0022","t":"Aspen Energy Inc. is a non-accelerated filer with a December 31 fiscal year-end. How many days after the end of each of the first three quarters is its Form 10-Q due?","mc":{"s":"Aspen Energy Inc. is a non-accelerated filer with a December 31 fiscal year-end. How many days after the end of each of the first three quarters is its Form 10-Q due?","d":"","o":["30 days","40 days","45 days","60 days"],"a":3,"cite":"Form 10-Q","rat":"Non-accelerated filers file the Form 10-Q within 45 days after quarter-end.","ex":["There is no 30-day 10-Q deadline for any filer category.","40 days applies to large accelerated and accelerated filers, not non-accelerated filers.","Non-accelerated filers file the Form 10-Q within 45 days after quarter-end.","60 days is the annual deadline for large accelerated filers on Form 10-K."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Form 10-Q is due 40 days after quarter-end for accelerated filers and 45 days for non-accelerated filers.","from":"2026-01-01","calc":1,"steps":["Non-accelerated: 45 days"]}},{"i":"FAR-I-D-0023","t":"On Monday, June 1, 2026, the board of Lantern Systems, a public company, approved the departure of its chief executive, a triggering event for Form 8-K. By when must Lantern file the Form 8-K?","mc":{"s":"On Monday, June 1, 2026, the board of Lantern Systems, a public company, approved the departure of its chief executive, a triggering event for Form 8-K. By when must Lantern file the Form 8-K?","d":"","o":["Wednesday, June 3, 2026","Thursday, June 4, 2026","Monday, June 8, 2026","Friday, June 5, 2026"],"a":4,"cite":"Form 8-K","rat":"A Form 8-K is due within four business days after the event: June 2, 3, 4 and 5.","ex":["This is two business days after the event, which is shorter than the four-business-day requirement.","This is three business days after the event; four are allowed.","This is five business days after the event, beyond the four-business-day deadline.","A Form 8-K is due within four business days after the event: June 2, 3, 4 and 5."],"wt":["limit","limit","limit",""],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Form 8-K is generally due within four business days after the triggering event.","from":"2026-01-01"}},{"i":"FAR-I-D-0024","t":"Which of the following misstatements is most likely to be material to a public company's financial statements even though it is quantitatively small?","mc":{"s":"Which of the following misstatements is most likely to be material to a public company's financial statements even though it is quantitatively small?","d":"","o":["A $200,000 overstatement, about 3% of pretax income, that converts a quarterly loss into a profit and lets the company meet analysts' consensus","A $200,000 misclassification within operating expenses that has no effect on net income, trends or covenant compliance","A $50,000 rounding difference on a schedule, about 0.5% of pretax income, that does not change any subtotal","A $200,000 timing difference offset in the next quarter, about 3% of pretax income, that reverses without any effect on trends"],"a":1,"cite":"SEC Staff Accounting Bulletin No. 99","rat":"Qualitative factors such as masking a change in earnings trend or meeting expectations can make a small misstatement material.","ex":["Qualitative factors such as masking a change in earnings trend or meeting expectations can make a small misstatement material.","A reclassification within one section with no earnings effect is unlikely to matter to investors.","A small rounding difference that changes nothing is not material.","A misstatement that has no effect on trends or expectations is less likely to be material."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Materiality considers qualitative factors, such as masking a trend or meeting expectations, as well as the size of the misstatement.","from":"2026-01-01"}}],"5":[{"i":"FAR-I-E-0001","t":"Pelham Services' accrual-basis revenue for 2026 was $800,000. During the year accounts receivable increased $30,000 and unearned revenue (cash received in advance) increased $12,000. What revenue would Pelham report on the cash basis?","mc":{"s":"Pelham Services' accrual-basis revenue for 2026 was $800,000. During the year accounts receivable increased $30,000 and unearned revenue (cash received in advance) increased $12,000. What revenue would Pelham report on the cash basis?","d":"","o":["$758,000","$782,000","$800,000","$842,000"],"a":2,"cite":"AICPA AU-C Section 800","rat":"Cash-basis revenue = $800,000 - $30,000 increase in receivables + $12,000 increase in unearned revenue = $782,000.","ex":["Subtracts the increase in unearned revenue; cash received in advance increases cash receipts.","Cash-basis revenue = $800,000 - $30,000 increase in receivables + $12,000 increase in unearned revenue = $782,000.","Reports the accrual amount without converting to cash receipts.","Adds the increase in receivables, which represents revenue not yet collected in cash."],"wt":["calc","","concept","calc"],"tags":{"area":"I","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Cash-basis revenue = accrual revenue - increase in receivables + increase in unearned revenue.","from":"2026-01-01","calc":1,"steps":["800000 - 30000 + 12000 = 782000"]}},{"i":"FAR-I-E-0002","t":"Rowan Co.'s accrual-basis expenses for 2026 were $600,000, including $50,000 of depreciation. Accounts payable increased $20,000 and prepaid expenses increased $15,000 during the year. What expenses would Rowan report on the cash basis? The depreciation relates to equipment bought in prior years, and no equipment was purchased in 2026.","mc":{"s":"Rowan Co.'s accrual-basis expenses for 2026 were $600,000, including $50,000 of depreciation. Accounts payable increased $20,000 and prepaid expenses increased $15,000 during the year. What expenses would Rowan report on the cash basis? The depreciation relates to equipment bought in prior years, and no equipment was purchased in 2026.","d":"","o":["$515,000","$545,000","$585,000","$595,000"],"a":2,"cite":"AICPA AU-C Section 800","rat":"$600,000 - $50,000 depreciation - $20,000 increase in payables + $15,000 increase in prepaids = $545,000.","ex":["Subtracts the prepaid increase; cash paid for prepaids in advance raises cash expenses.","$600,000 - $50,000 depreciation - $20,000 increase in payables + $15,000 increase in prepaids = $545,000.","Adds the increase in payables; unpaid amounts are not cash payments.","Leaves depreciation in the expenses, which is not a cash payment."],"wt":["calc","","calc","concept"],"tags":{"area":"I","group":"E","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Cash-basis expenses = accrual expenses - noncash items - increase in payables + increase in prepaids.","from":"2026-01-01","calc":1,"steps":["600000 - 50000 - 20000 + 15000 = 545000"]}},{"i":"FAR-I-E-0003","t":"On the cash basis, Whitby Corp. reported 2026 net income of $120,000. During the year: accounts receivable increased $30,000; unearned revenue decreased $10,000; accounts payable increased $25,000; prepaid expenses increased $8,000; and accrued salaries payable increased $12,000. What is accrual-basis net income?","mc":{"s":"On the cash basis, Whitby Corp. reported 2026 net income of $120,000. During the year: accounts receivable increased $30,000; unearned revenue decreased $10,000; accounts payable increased $25,000; prepaid expenses increased $8,000; and accrued salaries payable increased $12,000. What is accrual-basis net income?","d":"","o":["$101,000","$111,000","$115,000","$131,000"],"a":4,"cite":"AICPA AU-C Section 800","rat":"$120,000 + $30,000 receivables + $10,000 earned from prior advances - $25,000 payables + $8,000 prepaids - $12,000 accrued salaries = $131,000.","ex":["Ignores the increase in receivables, which adds accrual revenue not yet collected.","Subtracts the decrease in unearned revenue; the earned amount adds to accrual income.","Subtracts the prepaid increase; cash paid for future periods is not an expense, so it increases accrual income.","$120,000 + $30,000 receivables + $10,000 earned from prior advances - $25,000 payables + $8,000 prepaids - $12,000 accrued salaries = $131,000."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Accrual income = cash income + increases in receivables, earnings from unearned revenue and prepaids - increases in payables and accruals.","from":"2026-01-01","calc":1,"steps":["120000 + 30000 + 10000 - 25000 + 8000 - 12000 = 131000"]}},{"i":"FAR-I-E-0004","t":"Which of the following financial statement bases is an AICPA special purpose framework rather than U.S. GAAP?","mc":{"s":"Which of the following financial statement bases is an AICPA special purpose framework rather than U.S. GAAP?","d":"","o":["U.S. GAAP applied by a private company using accounting alternatives allowed for private companies","The income tax basis used by an entity to prepare its tax return","U.S. GAAP as issued by the Governmental Accounting Standards Board for state and local governments","U.S. GAAP for public companies, including SEC-specific guidance in the Codification"],"a":2,"cite":"AICPA AU-C Section 800","rat":"The tax basis, cash basis, regulatory basis and contractual basis are special purpose frameworks.","ex":["Private company alternatives are part of U.S. GAAP.","The tax basis, cash basis, regulatory basis and contractual basis are special purpose frameworks.","GASB standards are GAAP for governments.","This is GAAP, not a special purpose framework."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Special purpose frameworks include cash basis, tax basis, regulatory basis and contractual basis; GAAP and its alternatives are not special purpose.","from":"2026-01-01"}},{"i":"FAR-I-E-0005","t":"Ivy Partners prepares financial statements on the income tax basis. Which disclosure is required in the notes?","mc":{"s":"Ivy Partners prepares financial statements on the income tax basis. Which disclosure is required in the notes?","d":"","o":["Nothing, since the tax return already discloses the basis of accounting","A description of the tax basis and how it differs from GAAP, without quantifying the differences","A quantified reconciliation of tax-basis net income to GAAP net income for each period presented","A statement that the statements are in accordance with GAAP except for deferred taxes"],"a":2,"cite":"AICPA AU-C Section 800","rat":"The framework must be described, including the main differences from GAAP, but they need not be quantified.","ex":["The financial statements must describe the basis of accounting.","The framework must be described, including the main differences from GAAP, but they need not be quantified.","Quantification of differences from GAAP is not required.","The statements are not represented as GAAP."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Special purpose statements describe the framework and how it differs from GAAP; the differences need not be quantified.","from":"2026-01-01"}},{"i":"FAR-I-E-0006","t":"Book (GAAP) income before taxes of Alder Corp. was $500,000. Tax depreciation exceeded book depreciation by $40,000, the company earned $10,000 of tax-exempt interest included in book income, and it recorded $5,000 of nondeductible fines as an expense. What is income before taxes on the income tax basis, measured as taxable income is on the tax return (items excluded from or disallowed on the return are adjusted)?","mc":{"s":"Book (GAAP) income before taxes of Alder Corp. was $500,000. Tax depreciation exceeded book depreciation by $40,000, the company earned $10,000 of tax-exempt interest included in book income, and it recorded $5,000 of nondeductible fines as an expense. What is income before taxes on the income tax basis, measured as taxable income is on the tax return (items excluded from or disallowed on the return are adjusted)?","d":"","o":["$445,000","$455,000","$475,000","$535,000"],"a":2,"cite":"AICPA AU-C Section 800","rat":"$500,000 - $40,000 extra depreciation - $10,000 exempt interest + $5,000 nondeductible fines = $455,000.","ex":["Deducts the nondeductible fines; because the expense is not deductible for tax it is added back.","$500,000 - $40,000 extra depreciation - $10,000 exempt interest + $5,000 nondeductible fines = $455,000.","Adds the tax-exempt interest, which is excluded from taxable income.","Adds the excess tax depreciation; larger tax depreciation reduces taxable income."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Start from book income, subtract exempt income and excess tax deductions, and add back nondeductible expenses.","from":"2026-01-01","calc":1,"steps":["500000 - 40000 - 10000 + 5000 = 455000"]}},{"i":"FAR-I-E-0007","t":"Dale Marston prepares personal financial statements. His assets are cash of $50,000, marketable securities at current value of $400,000 (tax basis $250,000), and a business interest at estimated current value of $600,000 (tax basis $200,000). He owes notes payable of $120,000. The estimated tax rate on unrealized appreciation is 25%. What is Dale's net worth?","mc":{"s":"Dale Marston prepares personal financial statements. His assets are cash of $50,000, marketable securities at current value of $400,000 (tax basis $250,000), and a business interest at estimated current value of $600,000 (tax basis $200,000). He owes notes payable of $120,000. The estimated tax rate on unrealized appreciation is 25%. What is Dale's net worth?","d":"","o":["$655,000","$792,500","$912,500","$930,000"],"a":2,"cite":"ASC 274","rat":"Assets $1,050,000 less notes $120,000 less estimated taxes on the $550,000 of appreciation at 25% ($137,500) = $792,500.","ex":["Deducts the estimated income taxes twice.","Assets $1,050,000 less notes $120,000 less estimated taxes on the $550,000 of appreciation at 25% ($137,500) = $792,500.","Omits the notes payable, which are liabilities at current amounts.","Omits the estimated income taxes on the difference between current values and tax bases."],"wt":["calc","","concept","concept"],"tags":{"area":"I","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Personal statements report assets at estimated current value, liabilities at current amounts, and estimated taxes on unrealized appreciation.","from":"2026-01-01","calc":1,"steps":["Assets = 50,000 + 400,000 + 600,000 = 1,050,000","Appreciation = (400,000 - 250,000) + (600,000 - 200,000) = 550,000; tax at 25% = 137,500","Net worth = 1,050,000 - 120,000 - 137,500 = 792,500"]}},{"i":"FAR-I-E-0008","t":"Marisol Vega prepares personal financial statements. She holds a stock portfolio that she bought for $200,000 and that is worth $340,000 at year-end; the estimated income tax on the unrealized gain is $42,000. At what amount is the portfolio reported in her statement of financial condition?","mc":{"s":"Marisol Vega prepares personal financial statements. She holds a stock portfolio that she bought for $200,000 and that is worth $340,000 at year-end; the estimated income tax on the unrealized gain is $42,000. At what amount is the portfolio reported in her statement of financial condition?","d":"","o":["$200,000","$270,000","$298,000","$340,000"],"a":4,"cite":"ASC 274","rat":"Personal statements report assets at estimated current value, $340,000; the estimated taxes are shown separately as a liability-like item.","ex":["Reports historical cost, which is not used for personal financial statements.","Averages cost and current value, which has no basis.","Nets the estimated tax against the asset; the estimated taxes are presented separately.","Personal statements report assets at estimated current value, $340,000; the estimated taxes are shown separately as a liability-like item."],"wt":["concept","concept","trap",""],"tags":{"area":"I","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Personal financial statement assets are measured at estimated current values; estimated taxes on appreciation are reported separately.","from":"2026-01-01","calc":1,"steps":["Asset = current value 340,000"]}},{"i":"FAR-I-E-0009","t":"Quinn Dental prepares statements on a modified cash basis that capitalizes equipment and depreciates it straight-line. On July 1, 2026 it bought equipment for $90,000 in cash with a 10-year life and no salvage value. What depreciation expense should it report for 2026?","mc":{"s":"Quinn Dental prepares statements on a modified cash basis that capitalizes equipment and depreciates it straight-line. On July 1, 2026 it bought equipment for $90,000 in cash with a 10-year life and no salvage value. What depreciation expense should it report for 2026?","d":"","o":["$4,500","$9,000","$45,000","$90,000"],"a":1,"cite":"AICPA AU-C Section 800","rat":"$90,000 / 10 years x 6/12 = $4,500.","ex":["$90,000 / 10 years x 6/12 = $4,500.","Charges a full year of depreciation although the equipment was owned for six months.","Charges half the cost, which does not follow straight-line depreciation over ten years.","Expenses the whole cost as under a strict cash basis, which this framework does not use."],"wt":["","calc","calc","concept"],"tags":{"area":"I","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A modified cash basis may capitalize and depreciate long-lived assets while otherwise using cash receipts and disbursements.","from":"2026-01-01","calc":1,"steps":["90000/10 x 6/12 = 4500.0"]}},{"i":"FAR-I-E-0010","t":"A lender requires Cobalt Manufacturing to give annual financial statements prepared using the lender's definitions of revenue, inventory and current assets, which differ from GAAP, for use only by the lender. What framework are the statements prepared under?","mc":{"s":"A lender requires Cobalt Manufacturing to give annual financial statements prepared using the lender's definitions of revenue, inventory and current assets, which differ from GAAP, for use only by the lender. What framework are the statements prepared under?","d":"","o":["A contractual basis of accounting, a special purpose framework used to comply with an agreement","The regulatory basis, because a lender is a party that imposes rules on the reporting entity","The income tax basis, because the lender requires the statements to follow the tax return","U.S. GAAP, because all statements distributed to third parties must follow GAAP"],"a":1,"cite":"AICPA AU-C Section 800","rat":"Statements prepared to comply with a contract's requirements are prepared under a contractual basis, a special purpose framework.","ex":["Statements prepared to comply with a contract's requirements are prepared under a contractual basis, a special purpose framework.","The regulatory basis applies to requirements of a regulator, not a private lender.","The lender's terms, not the tax law, define the basis.","General distribution is not required; the contract's basis governs."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A contractual basis framework follows the reporting terms of an agreement, such as a loan covenant, and is a special purpose framework.","from":"2026-01-01"}},{"i":"FAR-I-E-0011","t":"Baker Design's cash receipts from customers in 2026 were $950,000. Accounts receivable were $90,000 at the beginning of the year and $120,000 at the end; unearned revenue was $40,000 at the beginning and $55,000 at the end. What is accrual-basis revenue for 2026?","mc":{"s":"Baker Design's cash receipts from customers in 2026 were $950,000. Accounts receivable were $90,000 at the beginning of the year and $120,000 at the end; unearned revenue was $40,000 at the beginning and $55,000 at the end. What is accrual-basis revenue for 2026?","d":"","o":["$905,000","$935,000","$965,000","$995,000"],"a":3,"cite":"AICPA AU-C Section 800","rat":"$950,000 + $30,000 increase in receivables - $15,000 increase in unearned revenue = $965,000.","ex":["Subtracts the receivable increase, though uncollected sales increase accrual revenue.","Reverses both adjustments, subtracting the receivable increase and adding the unearned revenue increase.","$950,000 + $30,000 increase in receivables - $15,000 increase in unearned revenue = $965,000.","Adds the unearned revenue increase, but cash received in advance is not yet earned revenue."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"E","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Accrual revenue = cash receipts + increase in receivables - increase in unearned revenue.","from":"2026-01-01","calc":1,"steps":["950000 + 30000 - 15000 = 965000"]}},{"i":"FAR-I-E-0012","t":"Which title is most appropriate for a balance-sheet-type statement prepared on the cash basis?","mc":{"s":"Which title is most appropriate for a balance-sheet-type statement prepared on the cash basis?","d":"","o":["Balance sheet, with a footnote that some amounts are recorded when cash is received or paid","Statement of financial position prepared in accordance with generally accepted accounting principles","Statement of assets, liabilities and equity - cash basis","Consolidated balance sheet under Financial Accounting Standards Board requirements"],"a":3,"cite":"AICPA AU-C Section 800","rat":"The title should indicate the basis so users are not misled into assuming GAAP.","ex":["An unqualified title may imply GAAP; the title should identify the basis.","The statements are not GAAP, so this title is misleading.","The title should indicate the basis so users are not misled into assuming GAAP.","Cash basis statements do not follow FASB requirements."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Titles for special purpose statements should identify the basis of accounting and avoid implying GAAP.","from":"2026-01-01"}}],"6":[{"i":"FAR-I-F-0001","t":"Brantley Co. has cash of $80,000, marketable securities of $40,000, net accounts receivable of $120,000, inventory of $200,000, prepaid expenses of $20,000, and current liabilities of $250,000. What is its quick (acid-test) ratio?","mc":{"s":"Brantley Co. has cash of $80,000, marketable securities of $40,000, net accounts receivable of $120,000, inventory of $200,000, prepaid expenses of $20,000, and current liabilities of $250,000. What is its quick (acid-test) ratio?","d":"","o":["0.48","0.96","1.76","1.84"],"a":2,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"($80,000 + $40,000 + $120,000) / $250,000 = 0.96.","ex":["Includes only cash and securities, which is the cash ratio.","($80,000 + $40,000 + $120,000) / $250,000 = 0.96.","Includes inventory in the numerator; inventory is excluded from the quick ratio.","Includes inventory and prepaids, which is the current ratio."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Quick ratio = (cash + marketable securities + net receivables) / current liabilities.","from":"2026-01-01","calc":1,"steps":["Quick assets = 240000","Ratio = 240000/250000 = 0.96"]}},{"i":"FAR-I-F-0002","t":"Cygnet Co. has current assets of $600,000 and current liabilities of $300,000. It pays $100,000 of accounts payable with cash. What is its current ratio after the payment?","mc":{"s":"Cygnet Co. has current assets of $600,000 and current liabilities of $300,000. It pays $100,000 of accounts payable with cash. What is its current ratio after the payment?","d":"","o":["1.67","2.00","2.50","3.00"],"a":3,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Current assets fall to $500,000 and current liabilities fall to $200,000, giving 2.50.","ex":["Reduces current assets but not current liabilities, ignoring that the payment settles the payable.","Leaves the ratio unchanged at 2.00, ignoring the effect of the payment on both amounts.","Current assets fall to $500,000 and current liabilities fall to $200,000, giving 2.50.","Reduces only current liabilities; the cash paid also reduces current assets."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"F","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Paying a current liability with cash lowers both current assets and current liabilities, raising a current ratio above 1.","from":"2026-01-01","calc":1,"steps":["After payment: CA 500,000; CL 200,000","Ratio 500,000 / 200,000 = 2.50"]}},{"i":"FAR-I-F-0003","t":"Sable Corp. has current assets of $400,000 and current liabilities of $500,000. Which single transaction would increase its current ratio?","mc":{"s":"Sable Corp. has current assets of $400,000 and current liabilities of $500,000. Which single transaction would increase its current ratio?","d":"","o":["Paying $50,000 of accounts payable with cash","Collecting $50,000 of accounts receivable in cash","Selling $50,000 of inventory at cost for cash","Purchasing $50,000 of inventory on account"],"a":4,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Adding $50,000 to both current assets and current liabilities moves a ratio below 1 closer to 1 (0.80 to 0.82).","ex":["Both amounts fall by $50,000, which lowers a ratio below 1 (0.80 to 0.78).","One current asset replaces another, so the current ratio is unchanged.","One current asset replaces another at the same amount, so the ratio is unchanged.","Adding $50,000 to both current assets and current liabilities moves a ratio below 1 closer to 1 (0.80 to 0.82)."],"wt":["concept","trap","trap",""],"tags":{"area":"I","group":"F","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"When the current ratio is below 1, adding equal amounts to current assets and liabilities raises it; paying liabilities with cash lowers it.","from":"2026-01-01"}},{"i":"FAR-I-F-0004","t":"Halcyon Co. had total sales of $2,700,000 in 2026, of which $300,000 were cash sales. Accounts receivable were $260,000 at the beginning and $340,000 at the end of the year. Using average receivables and a 365-day year, what is the average collection period (days sales outstanding) on credit sales?","mc":{"s":"Halcyon Co. had total sales of $2,700,000 in 2026, of which $300,000 were cash sales. Accounts receivable were $260,000 at the beginning and $340,000 at the end of the year. Using average receivables and a 365-day year, what is the average collection period (days sales outstanding) on credit sales?","d":"","o":["40 days","41 days","46 days","52 days"],"a":3,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Average receivables $300,000 / credit sales $2,400,000 x 365 = 46 days.","ex":["Uses only beginning receivables instead of the average.","Uses total sales including cash sales in the denominator, which understates the collection period.","Average receivables $300,000 / credit sales $2,400,000 x 365 = 46 days.","Uses only ending receivables instead of the average."],"wt":["calc","concept","","calc"],"tags":{"area":"I","group":"F","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Days sales outstanding = average receivables / net credit sales x 365.","from":"2026-01-01","calc":1,"steps":["Average AR = 300000","Credit sales = 2400000","DSO = 45.6 days"]}},{"i":"FAR-I-F-0005","t":"Delta Retail had sales of $2,400,000 and cost of goods sold of $1,800,000 in 2026. Inventory was $220,000 at the beginning of the year and $260,000 at the end. What is its inventory turnover?","mc":{"s":"Delta Retail had sales of $2,400,000 and cost of goods sold of $1,800,000 in 2026. Inventory was $220,000 at the beginning of the year and $260,000 at the end. What is its inventory turnover?","d":"","o":["6.9 times","7.5 times","8.2 times","10.0 times"],"a":2,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Cost of goods sold $1,800,000 / average inventory $240,000 = 7.5 times.","ex":["Uses ending inventory rather than average inventory.","Cost of goods sold $1,800,000 / average inventory $240,000 = 7.5 times.","Uses beginning inventory rather than average inventory.","Uses sales in the numerator, which overstates turnover; cost of goods sold is used."],"wt":["calc","","calc","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Inventory turnover = cost of goods sold / average inventory.","from":"2026-01-01","calc":1,"steps":["Average inventory = 240000","Turnover = 1800000/240000 = 7.5"]}},{"i":"FAR-I-F-0006","t":"Eastgate Corp. had credit sales of $2,920,000, cost of goods sold of $1,752,000, average receivables of $240,000, average inventory of $288,000, and average accounts payable of $192,000. Using a 365-day year, what is its cash conversion cycle in days?","mc":{"s":"Eastgate Corp. had credit sales of $2,920,000, cost of goods sold of $1,752,000, average receivables of $240,000, average inventory of $288,000, and average accounts payable of $192,000. Using a 365-day year, what is its cash conversion cycle in days?","d":"","o":["10 days","50 days","90 days","130 days"],"a":2,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Days sales outstanding 30 + days inventory outstanding 60 - days payable outstanding 40 = 50 days.","ex":["Subtracts inventory days and adds payables days, reversing the components.","Days sales outstanding 30 + days inventory outstanding 60 - days payable outstanding 40 = 50 days.","Omits the payables period, giving the operating cycle rather than the cash conversion cycle.","Adds the payables period instead of subtracting it; suppliers finance part of the cycle."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"F","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Cash conversion cycle = days sales outstanding + days inventory outstanding - days payables outstanding.","from":"2026-01-01","calc":1,"steps":["DSO = 240,000/2,920,000 x 365 = 30","DIO = 288,000/1,752,000 x 365 = 60","DPO = 192,000/1,752,000 x 365 = 40","CCC = 30 + 60 - 40 = 50"]}},{"i":"FAR-I-F-0007","t":"Fairmont Inc. reports total liabilities of $900,000, total stockholders' equity of $600,000, and total assets of $1,500,000. What is its debt-to-equity ratio?","mc":{"s":"Fairmont Inc. reports total liabilities of $900,000, total stockholders' equity of $600,000, and total assets of $1,500,000. What is its debt-to-equity ratio?","d":"","o":["0.60","0.67","1.50","2.50"],"a":3,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"$900,000 / $600,000 = 1.50.","ex":["Divides liabilities by assets, which is the debt ratio (0.60).","Inverts the ratio (equity to liabilities, 0.67).","$900,000 / $600,000 = 1.50.","Divides assets by equity, which is the equity multiplier (2.50)."],"wt":["concept","calc","","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Debt-to-equity = total liabilities / total stockholders' equity.","from":"2026-01-01","calc":1,"steps":["900000/600000 = 1.50"]}},{"i":"FAR-I-F-0008","t":"Gilroy Co. reported net income of $240,000, income tax expense of $80,000 and interest expense of $60,000. What is its times interest earned ratio?","mc":{"s":"Gilroy Co. reported net income of $240,000, income tax expense of $80,000 and interest expense of $60,000. What is its times interest earned ratio?","d":"","o":["4.00","5.33","6.33","7.33"],"a":3,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Earnings before interest and taxes $380,000 / interest $60,000 = 6.33.","ex":["Uses net income, which is after interest and taxes.","Uses earnings before taxes but after interest; interest must be added back.","Earnings before interest and taxes $380,000 / interest $60,000 = 6.33.","Adds interest a second time to earnings before interest and taxes."],"wt":["concept","concept","","calc"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Times interest earned = earnings before interest and taxes / interest expense.","from":"2026-01-01","calc":1,"steps":["EBIT = 240000+80000+60000 = 380000","Ratio = 6.33"]}},{"i":"FAR-I-F-0009","t":"Hamlin Corp. reported net income of $180,000 and preferred dividends of $20,000. Common stockholders' equity was $700,000 at the beginning and $900,000 at the end of the year; preferred equity was $200,000 at both dates. What is return on common equity based on average balances?","mc":{"s":"Hamlin Corp. reported net income of $180,000 and preferred dividends of $20,000. Common stockholders' equity was $700,000 at the beginning and $900,000 at the end of the year; preferred equity was $200,000 at both dates. What is return on common equity based on average balances?","d":"","o":["16.0%","18.0%","20.0%","22.5%"],"a":3,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"($180,000 - $20,000) / average common equity $800,000 = 20.0%.","ex":["Deducts preferred dividends but leaves preferred equity in the denominator.","Uses net income and total equity including preferred, which mismatches the numerator and denominator.","($180,000 - $20,000) / average common equity $800,000 = 20.0%.","Does not deduct preferred dividends from net income."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"F","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Return on common equity = (net income - preferred dividends) / average common stockholders' equity.","from":"2026-01-01","calc":1,"steps":["Numerator = 160000; average common equity = 800000","Return = 20.0%"]}},{"i":"FAR-I-F-0010","t":"Ivory Products reported net income of $120,000 on sales of $1,500,000. Average total assets were $1,000,000 and average stockholders' equity was $400,000. What is return on equity?","mc":{"s":"Ivory Products reported net income of $120,000 on sales of $1,500,000. Average total assets were $1,000,000 and average stockholders' equity was $400,000. What is return on equity?","d":"","o":["4.8%","8.0%","12.0%","30.0%"],"a":4,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Margin 8.0% x asset turnover 1.5 x equity multiplier 2.5 = 30.0%; equivalently $120,000 / $400,000.","ex":["Multiplies return on assets by the inverse of the equity multiplier, which reduces rather than raises the return.","Reports only the net profit margin (8.0%).","Reports return on assets (12.0%), which omits financial leverage.","Margin 8.0% x asset turnover 1.5 x equity multiplier 2.5 = 30.0%; equivalently $120,000 / $400,000."],"wt":["calc","concept","concept",""],"tags":{"area":"I","group":"F","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"ROE = profit margin x asset turnover x equity multiplier = net income / average equity.","from":"2026-01-01","calc":1,"steps":["Margin = 120,000/1,500,000 = 8.0%","Asset turnover = 1,500,000/1,000,000 = 1.5","Equity multiplier = 1,000,000/400,000 = 2.5","ROE = 8.0% x 1.5 x 2.5 = 30.0%"]}},{"i":"FAR-I-F-0011","t":"Juniper Inc.'s return on equity rose from 15% to 18%. Over the same period its net profit margin fell from 6.0% to 5.0%, and its asset turnover rose from 1.50 to 1.60. Which conclusion is best supported?","mc":{"s":"Juniper Inc.'s return on equity rose from 15% to 18%. Over the same period its net profit margin fell from 6.0% to 5.0%, and its asset turnover rose from 1.50 to 1.60. Which conclusion is best supported?","d":"","o":["The increase came from higher financial leverage, which more than offset the lower margin","The increase came from improved profitability, because the higher asset turnover raised the net profit margin","The increase came from better asset utilization alone, because turnover rose while leverage stayed constant","The increase came from higher profit margins, because margin and turnover both affect return on equity"],"a":1,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"The equity multiplier rose from about 1.67 to 2.25, raising ROE despite the lower margin and modestly better turnover.","ex":["The equity multiplier rose from about 1.67 to 2.25, raising ROE despite the lower margin and modestly better turnover.","The margin actually fell; turnover is a separate driver.","Turnover rose only about 7%, not enough; leverage rose about 35%.","The profit margin declined."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"F","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"ROE = margin x turnover x leverage; solve the implied equity multiplier to identify the driver of a change.","from":"2026-01-01"}},{"i":"FAR-I-F-0012","t":"Kirby Corp. reported sales of $2,000,000, cost of goods sold of $1,300,000, operating expenses of $450,000, interest expense of $30,000 and income tax expense of $50,000. What is its net profit margin?","mc":{"s":"Kirby Corp. reported sales of $2,000,000, cost of goods sold of $1,300,000, operating expenses of $450,000, interest expense of $30,000 and income tax expense of $50,000. What is its net profit margin?","d":"","o":["8.5%","11.0%","12.5%","35.0%"],"a":1,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Net income $170,000 / sales $2,000,000 = 8.5%.","ex":["Net income $170,000 / sales $2,000,000 = 8.5%.","Stops before deducting income taxes, giving a pretax margin of 11.0%.","Stops before deducting interest and taxes, giving an operating margin of 12.5%.","Reports the gross margin of 35.0%."],"wt":["","calc","calc","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Net profit margin = net income / net sales.","from":"2026-01-01","calc":1,"steps":["Net income = 170000","Margin = 8.5%"]}},{"i":"FAR-I-F-0013","t":"Lakeside Corp. earned $3.50 per share in 2026, paid dividends of $1.40 per share, and its stock closed the year at $42.00. What is its price-earnings ratio?","mc":{"s":"Lakeside Corp. earned $3.50 per share in 2026, paid dividends of $1.40 per share, and its stock closed the year at $42.00. What is its price-earnings ratio?","d":"","o":["3.3","12.0","30.0","40.0"],"a":2,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"$42.00 / $3.50 = 12.0.","ex":["Divides dividends by price, which gives the dividend yield of 3.3%.","$42.00 / $3.50 = 12.0.","Divides price by dividends per share, giving 30.0.","Divides dividends by earnings, which gives the payout ratio of 40.0%."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Price-earnings ratio = market price per share / earnings per share.","from":"2026-01-01","calc":1,"steps":["42.00 / 3.50 = 12.0"]}},{"i":"FAR-I-F-0014","t":"Mulberry Inc. has total stockholders' equity of $2,400,000, which includes preferred stock with a liquidation value of $400,000 and no dividends in arrears. It has 520,000 common shares issued, of which 20,000 are held as treasury stock. What is book value per common share?","mc":{"s":"Mulberry Inc. has total stockholders' equity of $2,400,000, which includes preferred stock with a liquidation value of $400,000 and no dividends in arrears. It has 520,000 common shares issued, of which 20,000 are held as treasury stock. What is book value per common share?","d":"","o":["$3.85","$4.00","$4.62","$4.80"],"a":2,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"($2,400,000 - $400,000) / 500,000 shares outstanding = $4.00.","ex":["Divides by issued shares instead of outstanding shares.","($2,400,000 - $400,000) / 500,000 shares outstanding = $4.00.","Does not remove the preferred equity and uses issued shares.","Does not remove the preferred equity from the numerator."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Book value per common share = (total equity - preferred equity) / common shares outstanding.","from":"2026-01-01","calc":1,"steps":["Common equity = 2000000; shares outstanding = 500000","BVPS = 4.00"]}},{"i":"FAR-I-F-0015","t":"Over two years, Nolan Co.'s receivables turnover fell from 9.0 to 6.5, its inventory turnover rose from 5.0 to 7.0, and its gross margin percentage was unchanged. Which explanation is most consistent with these trends?","mc":{"s":"Over two years, Nolan Co.'s receivables turnover fell from 9.0 to 6.5, its inventory turnover rose from 5.0 to 7.0, and its gross margin percentage was unchanged. Which explanation is most consistent with these trends?","d":"","o":["Credit terms were tightened and collections accelerated, while inventory levels grew relative to sales","Both working capital accounts became more efficient, which is why gross margin stayed the same","Credit terms were loosened or collections slowed, while inventory management became tighter","Both working capital accounts became less efficient, offset by an increase in sales prices"],"a":3,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Lower receivables turnover signals slower collections; higher inventory turnover signals faster movement of goods.","ex":["Both signals point the opposite way: receivables slowed and inventory speeded up.","Receivables turnover fell, which is less efficient.","Lower receivables turnover signals slower collections; higher inventory turnover signals faster movement of goods.","Inventory turnover rose, which is more efficient, and prices would change gross margin."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"F","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Lower receivables turnover means slower collection; higher inventory turnover means inventory is moving faster.","from":"2026-01-01"}},{"i":"FAR-I-F-0016","t":"Oriole Corp. reported net cash provided by operating activities of $500,000, purchases of property and equipment of $300,000, and dividends paid of $100,000. What is its free cash flow (operating cash flow less capital expenditures)?","mc":{"s":"Oriole Corp. reported net cash provided by operating activities of $500,000, purchases of property and equipment of $300,000, and dividends paid of $100,000. What is its free cash flow (operating cash flow less capital expenditures)?","d":"","o":["$100,000","$200,000","$400,000","$500,000"],"a":2,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"$500,000 - $300,000 = $200,000.","ex":["Also deducts dividends, which are not part of the standard free cash flow definition.","$500,000 - $300,000 = $200,000.","Deducts dividends instead of capital expenditures.","Reports operating cash flow without deducting capital expenditures."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Free cash flow = cash from operating activities - capital expenditures.","from":"2026-01-01","calc":1,"steps":["500000 - 300000 = 200000"]}},{"i":"FAR-I-F-0017","t":"Pinnacle Co. reported net income of $200,000, interest expense of $40,000, an income tax rate of 25%, and average total assets of $2,000,000 (ending assets $2,200,000). Using return on assets defined as net income plus after-tax interest, divided by average total assets, what is the ratio?","mc":{"s":"Pinnacle Co. reported net income of $200,000, interest expense of $40,000, an income tax rate of 25%, and average total assets of $2,000,000 (ending assets $2,200,000). Using return on assets defined as net income plus after-tax interest, divided by average total assets, what is the ratio?","d":"","o":["10.0%","10.5%","11.5%","12.0%"],"a":3,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"($200,000 + $30,000 after-tax interest) / $2,000,000 = 11.5%.","ex":["Uses net income only, without adding back after-tax interest (10.0%).","Uses ending assets instead of average assets (10.5%).","($200,000 + $30,000 after-tax interest) / $2,000,000 = 11.5%.","Adds back interest before tax (12.0%), although interest expense saved a tax deduction."],"wt":["concept","concept","","concept"],"tags":{"area":"I","group":"F","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"ROA = (net income + interest expense x (1 - tax rate)) / average total assets.","from":"2026-01-01","calc":1,"steps":["After-tax interest = 40000x0.75 = 30000","ROA = 11.5%"]}},{"i":"FAR-I-F-0018","t":"Rowland Inc. reported revenues of $4.0 million in 2025 and $4.6 million in 2026, and operating expenses (including cost of sales) of $3.6 million in 2025 and $4.3 million in 2026. What was the percentage change in operating income from 2025 to 2026?","mc":{"s":"Rowland Inc. reported revenues of $4.0 million in 2025 and $4.6 million in 2026, and operating expenses (including cost of sales) of $3.6 million in 2025 and $4.3 million in 2026. What was the percentage change in operating income from 2025 to 2026?","d":"","o":["-25.0%","15.0%","19.4%","25.0%"],"a":1,"cite":"AICPA FAR Blueprint Area I: financial ratio analysis (no codification guidance)","rat":"Operating income fell from $400,000 to $300,000, a change of -25.0%.","ex":["Operating income fell from $400,000 to $300,000, a change of -25.0%.","Reports the 15.0% growth in revenue, not in operating income.","Reports the 19.4% growth in expenses, not in operating income.","Reports the size of the change (25.0%) with the wrong sign; operating income declined."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Horizontal analysis measures the percentage change in a line item from a base period; here operating income fell 25%.","from":"2026-01-01","calc":1,"steps":["Operating income 2025 = 4,000,000 - 3,600,000 = 400,000","Operating income 2026 = 4,600,000 - 4,300,000 = 300,000","Change = (300,000 - 400,000) / 400,000 = -25.0%"]}}]};
